package darksafe

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"math/big"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf16"
	"unicode/utf8"
)

// Point 是一条序列上某个时间戳的采样值。
type Point struct {
	Timestamp int64   `json:"timestamp"`
	Value     float64 `json:"value"`
}

// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
type SeriesView struct {
	Name   string            `json:"name"`
	Labels map[string]string `json:"labels"`
	Points []Point           `json:"points"`
}

// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
type QuerySeries struct {
	Name    string            `json:"name"`
	Labels  map[string]string `json:"labels"`
	Count   int               `json:"count"`
	Average float64           `json:"average"`
}

// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
type QueryResult struct {
	Status string        `json:"status"`
	Op     string        `json:"op"`
	Series []QuerySeries `json:"series"`
}

// QueryPointsSeries 是采样明细查询结果中的一条序列：完整身份与区间内
// 按时间戳升序排列的采样点，不附带点数或平均值。
type QueryPointsSeries struct {
	Name   string            `json:"name"`
	Labels map[string]string `json:"labels"`
	Points []Point           `json:"points"`
}

// QueryPointsResult 是一次区间采样明细查询（op 为 query_points）成功后的结果，
// 只读，不改变存储。
type QueryPointsResult struct {
	Status string              `json:"status"`
	Op     string              `json:"op"`
	Series []QueryPointsSeries `json:"series"`
}

// Window 是固定时间窗口统计中的一个窗口：[Start,End] 闭区间（含首尾毫秒）内
// 已成功保存的点的个数与算术平均值。空窗口不会出现——只有实际有点的窗口才列出。
type Window struct {
	Start   int64   `json:"start"`
	End     int64   `json:"end"`
	Count   int     `json:"count"`
	Average float64 `json:"average"`
}

// QueryWindowsSeries 是固定窗口均值查询结果中的一条序列：完整身份与按窗口起点
// 升序排列的窗口统计，空窗口不补零。
type QueryWindowsSeries struct {
	Name    string            `json:"name"`
	Labels  map[string]string `json:"labels"`
	Windows []Window          `json:"windows"`
}

// QueryWindowsResult 是一次固定时间窗口均值查询（op 为 query_windows）成功后的
// 结果，只读，不改变存储。
type QueryWindowsResult struct {
	Status string               `json:"status"`
	Op     string               `json:"op"`
	Series []QueryWindowsSeries `json:"series"`
}

// BatchResult 是一批采样点写入成功后的结果。
type BatchResult struct {
	Status     string       `json:"status"`
	Added      int          `json:"added"`
	Duplicates int          `json:"duplicates"`
	Series     []SeriesView `json:"series"`
}

// SeriesRef 标识一条序列：指标名加完整标签集合。
// 缺少某个标签与该标签值为空字符串属于不同序列。
type SeriesRef struct {
	Name   string            `json:"name"`
	Labels map[string]string `json:"labels"`
}

// Conflict 描述同一序列同一时间戳已存在不同的值。
type Conflict struct {
	Series    SeriesRef `json:"series"`
	Timestamp int64     `json:"timestamp"`
	Existing  float64   `json:"existing"`
	Submitted float64   `json:"submitted"`
}

// LineError 是一行（一批）输入失败后的结构化结果。
// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
type LineError struct {
	Status   string    `json:"status"`
	Line     int       `json:"line,omitempty"`
	Index    int       `json:"index,omitempty"`
	Error    string    `json:"error"`
	Conflict *Conflict `json:"conflict,omitempty"`
}

// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
type MetricStore struct {
	series map[seriesID]*storedSeries
}

// seriesID 是序列的规范身份，标签书写顺序不影响身份。
type seriesID struct {
	name string
	// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
	sig string
}

type storedSeries struct {
	ref    SeriesRef
	points map[int64]float64
}

// NewMetricStore 创建一个空的指标存储。
func NewMetricStore() *MetricStore {
	return &MetricStore{series: make(map[seriesID]*storedSeries)}
}

// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
// 调用方对副本的增删改不影响存储中的序列身份。
func cloneLabels(labels map[string]string) map[string]string {
	out := make(map[string]string, len(labels))
	for k, v := range labels {
		out[k] = v
	}
	return out
}

func sortedKeys(m map[string]string) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func makeSeriesID(name string, labels map[string]string) seriesID {
	var b strings.Builder
	for _, k := range sortedKeys(labels) {
		v := labels[k]
		fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
	}
	return seriesID{name: name, sig: b.String()}
}

// labelPair 是标签键值对字典序比较的单元。
type labelPair struct {
	Key, Value string
}

func sortedPairs(labels map[string]string) []labelPair {
	keys := sortedKeys(labels)
	pairs := make([]labelPair, len(keys))
	for i, k := range keys {
		pairs[i] = labelPair{Key: k, Value: labels[k]}
	}
	return pairs
}

func compareLabelPairs(a, b []labelPair) int {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i].Key != b[i].Key {
			return strings.Compare(a[i].Key, b[i].Key)
		}
		if a[i].Value != b[i].Value {
			return strings.Compare(a[i].Value, b[i].Value)
		}
	}
	switch {
	case len(a) < len(b):
		return -1
	case len(a) > len(b):
		return 1
	}
	return 0
}

var (
	jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
	jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
)

// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
// 成功时返回非 nil 的 *BatchResult、*QueryResult、*QueryPointsResult 或
// *QueryWindowsResult 且错误为 nil；任何失败都返回真正的 nil 结果与 *LineError，
// 调用方直接比较 result == nil 即可判定失败，无须先区分结果类型。空写入数组与
// 无命中的查询仍是成功，结果不为 nil。
func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
	top, ok, lerr := decodeTopValue(line)
	if lerr != nil {
		return nil, lerr
	}
	switch ok {
	case '[':
		var items []json.RawMessage
		if err := json.Unmarshal(top, &items); err != nil {
			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
		}
		// 不能把 *BatchResult 直接装进 any 返回：失败时它是带类型的 nil 指针，
		// 接口值非 nil，调用方会把失败误判为有结果。
		batch, lerr := s.ingestItems(items)
		if lerr != nil {
			return nil, lerr
		}
		return batch, nil
	case '{':
		// 同上：失败时不能把带类型 nil 的结果指针装进 any。
		return s.queryFromObject(top)
	default:
		return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
	}
}

// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
	top, ok, lerr := decodeTopValue(line)
	if lerr != nil {
		return nil, lerr
	}
	if ok != '[' {
		return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
	}
	var items []json.RawMessage
	if err := json.Unmarshal(top, &items); err != nil {
		return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
	}
	return s.ingestItems(items)
}

// QueryLine 解析并执行一行 op 为 "query" 的区间均值查询对象。成功返回 QueryResult；
// 查询只读，不改变存储。op 为 "query_points" 的采样明细查询由 QueryPointsLine
// 执行，op 为 "query_windows" 的固定窗口均值查询由 QueryWindowsLine 执行。
func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
	top, ok, lerr := decodeTopValue(line)
	if lerr != nil {
		return nil, lerr
	}
	if ok != '{' {
		return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
	}
	res, lerr := s.queryFromObject(top)
	if lerr != nil {
		return nil, lerr
	}
	qr, isQuery := res.(*QueryResult)
	if !isQuery {
		if _, isPoints := res.(*QueryPointsResult); isPoints {
			return nil, &LineError{Status: "error", Error: `op "query_points" lists sample points; use QueryPointsLine`}
		}
		return nil, &LineError{Status: "error", Error: `op "query_windows" lists fixed-window averages; use QueryWindowsLine`}
	}
	return qr, nil
}

// QueryWindowsLine 解析并执行一行 op 为 "query_windows" 的固定时间窗口均值查询
// 对象。成功返回 QueryWindowsResult；查询只读，不改变存储。
func (s *MetricStore) QueryWindowsLine(line string) (*QueryWindowsResult, *LineError) {
	top, ok, lerr := decodeTopValue(line)
	if lerr != nil {
		return nil, lerr
	}
	if ok != '{' {
		return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
	}
	res, lerr := s.queryFromObject(top)
	if lerr != nil {
		return nil, lerr
	}
	qw, isWindows := res.(*QueryWindowsResult)
	if !isWindows {
		if _, isPoints := res.(*QueryPointsResult); isPoints {
			return nil, &LineError{Status: "error", Error: `op "query_points" lists sample points; use QueryPointsLine`}
		}
		return nil, &LineError{Status: "error", Error: `op "query" computes range statistics; use QueryLine`}
	}
	return qw, nil
}

// QueryPointsLine 解析并执行一行 op 为 "query_points" 的区间采样明细查询对象。
// 成功返回 QueryPointsResult；查询只读，不改变存储。
func (s *MetricStore) QueryPointsLine(line string) (*QueryPointsResult, *LineError) {
	top, ok, lerr := decodeTopValue(line)
	if lerr != nil {
		return nil, lerr
	}
	if ok != '{' {
		return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
	}
	res, lerr := s.queryFromObject(top)
	if lerr != nil {
		return nil, lerr
	}
	qp, isPoints := res.(*QueryPointsResult)
	if !isPoints {
		if _, isWindows := res.(*QueryWindowsResult); isWindows {
			return nil, &LineError{Status: "error", Error: `op "query_windows" lists fixed-window averages; use QueryWindowsLine`}
		}
		return nil, &LineError{Status: "error", Error: `op "query" computes range statistics; use QueryLine`}
	}
	return qp, nil
}

// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
//
// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
func validateLineText(line string) *LineError {
	if !utf8.ValidString(line) {
		return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
	}
	inString := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if !inString {
			if c == '"' {
				inString = true
			}
			continue
		}
		switch c {
		case '"':
			inString = false
		case '\\':
			if i+1 >= len(line) {
				break // 悬空反斜杠：交给 JSON 解析器报错
			}
			if line[i+1] != 'u' {
				i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
				continue
			}
			// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
			r, size := decodeJSONHexEscape(line, i+1)
			if size == 0 {
				return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
			}
			if !utf16.IsSurrogate(r) {
				i += 5
				continue
			}
			if r >= 0xDC00 {
				// 单独出现的低代理项。
				return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
			}
			// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
			loPos := i + 6 // 第一个转义之后的字符位置
			if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
				return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
			}
			lo, loSize := decodeJSONHexEscape(line, loPos+1)
			if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
				return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
			}
			i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
		}
	}
	return nil
}

// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
func decodeJSONHexEscape(line string, pos int) (rune, int) {
	if pos+4 >= len(line) {
		return 0, 0
	}
	var v rune
	for j := pos + 1; j <= pos+4; j++ {
		c := line[j]
		var d rune
		switch {
		case c >= '0' && c <= '9':
			d = rune(c - '0')
		case c >= 'a' && c <= 'f':
			d = rune(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = rune(c-'A') + 10
		default:
			return 0, 0
		}
		v = v<<4 | d
	}
	return v, 5
}

// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
	if lerr := validateLineText(line); lerr != nil {
		return nil, 0, lerr
	}
	dec := json.NewDecoder(strings.NewReader(line))
	var top json.RawMessage
	if err := dec.Decode(&top); err != nil {
		return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
	}
	// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
	if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("unexpected content after the JSON value")
		}
		return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
	}
	trimmed := strings.TrimSpace(string(top))
	if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
		return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
	}
	return top, trimmed[0], nil
}

// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
// 采样点与查询对象各自注册自己允许的字段及字段含义。
type fieldReader func(dec *json.Decoder) error

// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
// 保留各自输入的措辞。
func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()

	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return fmt.Errorf("%s", notObjectMsg)
	}

	present := make(map[string]bool)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		key := keyTok.(string)
		read, ok := fields[key]
		if !ok {
			return fmt.Errorf("unknown field %q", key)
		}
		if present[key] {
			return fmt.Errorf("duplicate field %q", key)
		}
		present[key] = true
		if err := read(dec); err != nil {
			return err
		}
	}
	if _, err := dec.Token(); err != nil { // 消耗 '}'
		return err
	}
	if _, err := dec.Token(); err != io.EOF {
		if err == nil {
			return fmt.Errorf("%s", trailingMsg)
		}
		return err
	}

	for _, field := range required {
		if !present[field] {
			return fmt.Errorf("missing required field %q", field)
		}
	}
	return nil
}

// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
func readNameField(dec *json.Decoder, dst *string) error {
	t, err := dec.Token()
	if err != nil {
		return err
	}
	s, ok := t.(string)
	if !ok {
		return fmt.Errorf(`field "name" must be a string`)
	}
	if s == "" {
		return fmt.Errorf(`field "name" must be a non-empty string`)
	}
	*dst = s
	return nil
}

// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
	n, err := nextJSONNumber(dec, field)
	if err != nil {
		return err
	}
	v, err := parseJSONInt(n)
	if err != nil {
		return fmt.Errorf("field %q: %s", field, err)
	}
	*dst = v
	return nil
}

// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
	n, err := nextJSONNumber(dec, field)
	if err != nil {
		return err
	}
	v, err := parseFiniteFloat(n)
	if err != nil {
		return fmt.Errorf("field %q: %s", field, err)
	}
	*dst = v
	return nil
}

// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
	labels, err := parseLabels(dec, notObjectMsg)
	if err != nil {
		return err
	}
	*dst = labels
	return nil
}

type parsedSample struct {
	name   string
	ts     int64
	value  float64
	labels map[string]string
}

// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
func parseSample(raw json.RawMessage) (parsedSample, error) {
	var p parsedSample
	p.labels = map[string]string{}
	err := parseStrictObject(raw,
		"each sample must be a JSON object",
		"unexpected content after the sample object",
		[]string{"name", "timestamp", "value"},
		map[string]fieldReader{
			"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
			"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
			"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
			"labels": func(dec *json.Decoder) error {
				return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
			},
		})
	return p, err
}

// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
// 判重先于值的类型校验：某个键第一次出现时若值不是字符串，仍报告该值的类型
// 错误；而该键再次出现时，无论第二次的值是什么（数字、布尔、null、对象、数组），
// 都先报告重复标签键，不能让第二次值的类型掩盖键重复。
// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	d, ok := t.(json.Delim)
	if !ok || d != '{' {
		return nil, fmt.Errorf("%s", notObjectMsg)
	}
	labels := map[string]string{}
	for dec.More() {
		labelKeyTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		labelKey := labelKeyTok.(string)
		if labelKey == "" {
			return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
		}
		// 先判重再读值：与采样点/查询字段的判重一致，重复键不被值的类型掩盖。
		if _, dup := labels[labelKey]; dup {
			return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
		}
		valTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		labelVal, ok := valTok.(string)
		if !ok {
			return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
		}
		labels[labelKey] = labelVal
	}
	if _, err := dec.Token(); err != nil { // 消耗 '}'
		return nil, err
	}
	return labels, nil
}

func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
	t, err := dec.Token()
	if err != nil {
		return "", err
	}
	n, ok := t.(json.Number)
	if !ok {
		return "", fmt.Errorf(`field %q must be a JSON number`, field)
	}
	return n, nil
}

func parseJSONInt(n json.Number) (int64, error) {
	s := string(n)
	if !jsonIntegerRE.MatchString(s) {
		return 0, fmt.Errorf("must be a JSON integer in milliseconds")
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("must be within int64 range")
	}
	return v, nil
}

func parseFiniteFloat(n json.Number) (float64, error) {
	s := string(n)
	if !jsonNumberRE.MatchString(s) {
		return 0, fmt.Errorf("must be a JSON number")
	}
	v, err := strconv.ParseFloat(s, 64)
	if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
		return 0, fmt.Errorf("must be a finite number representable as float64")
	}
	return v, nil
}

// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
	type pending struct {
		id  seriesID
		ref SeriesRef
		ts  int64
		val float64
	}

	added := 0
	// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
	seen := make(map[seriesID]map[int64]float64)
	// 仅记录需要落盘的新增点；校验全部通过后才提交。
	commits := make([]pending, 0, len(items))

	failAt := func(index int, msg string) *LineError {
		return &LineError{Status: "error", Index: index, Error: msg}
	}
	conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
		return &LineError{
			Status: "error",
			Index:  index,
			Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
				ref, ts, formatFloat(existing), formatFloat(submitted)),
			Conflict: &Conflict{
				// 标签必须复制：冲突结果是本次失败的独立记录，
				// 调用方修改它不能改动已存序列的身份。
				Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
				Timestamp: ts,
				Existing:  existing,
				Submitted: submitted,
			},
		}
	}

	for i, item := range items {
		pos := i + 1
		p, err := parseSample(item)
		if err != nil {
			return nil, failAt(pos, err.Error())
		}

		id := makeSeriesID(p.name, p.labels)
		ref := SeriesRef{Name: p.name, Labels: p.labels}

		// 同一采样位置无论值来自本批较早接受的点还是此前批次已写入的点，
		// 都走同一条判定：转换后的 float64 相等即重复、成功忽略，不同即冲突、
		// 整批拒绝。existing 是该位置当前生效的值，两种来源下语义一致。
		if existing, ok := s.positionValue(seen, id, p.ts); ok {
			if existing != p.value {
				return nil, conflictAt(pos, ref, p.ts, existing, p.value)
			}
			// 等值重复：成功忽略。seen 记录的是生效值 existing 而不是本次
			// 提交的 p.value：数值相等但表示不同（如已存 -0、本次提交 +0）时，
			// 本批后续在同位置的冲突必须如实报告最先接受的值，
			// 不能被这条被忽略的重复改写。
			if seen[id] == nil {
				seen[id] = map[int64]float64{}
			}
			seen[id][p.ts] = existing
			continue
		}

		added++
		if seen[id] == nil {
			seen[id] = map[int64]float64{}
		}
		seen[id][p.ts] = p.value
		commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
	}

	// 全部采样点合法且无冲突，原子提交本批新增点。
	for _, c := range commits {
		sr := s.series[c.id]
		if sr == nil {
			sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
			s.series[c.id] = sr
		}
		sr.points[c.ts] = c.val
	}

	return s.snapshot(added, len(items)-added), nil
}

// positionValue 解析一个采样位置（序列身份 + 时间戳）当前生效的值：
// 本批已接受的值优先（含与已写入数据等值而被忽略的重复所登记的生效值），
// 其次是此前批次已成功写入的值；该位置没有任何数据时 ok 为 false。
// 重复与冲突判定只看这里返回的值，不再区分两种来源。
func (s *MetricStore) positionValue(seen map[seriesID]map[int64]float64, id seriesID, ts int64) (value float64, ok bool) {
	if byTS, found := seen[id]; found {
		if v, hit := byTS[ts]; hit {
			return v, true
		}
	}
	if sr, found := s.series[id]; found {
		if v, hit := sr.points[ts]; hit {
			return v, true
		}
	}
	return 0, false
}

// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
func formatFloat(v float64) string {
	return strconv.FormatFloat(v, 'g', -1, 64)
}

type parsedQuery struct {
	op        string
	name      string
	start     int64
	end       int64
	labels    map[string]string
	step      int64
	stepGiven bool
	// basicGiven 记录 op/name/start/end 四个基础字段是否在对象中出现过：
	// 必填检查不能用零值判断（0 与空串可能就是合法输入）。
	basicGiven map[string]bool
}

// queryFromObject 严格解析查询对象并执行对应的只读操作：op 为 "query" 时
// 统计区间内点数与均值，为 "query_points" 时列出区间内采样明细，为
// "query_windows" 时按固定宽度时间窗口分别统计点数与均值。
// 成功返回非 nil 的 *QueryResult、*QueryPointsResult 或 *QueryWindowsResult；
// 失败返回 nil 与 *LineError。
func (s *MetricStore) queryFromObject(raw json.RawMessage) (any, *LineError) {
	q, err := parseQuery(raw)
	if err != nil {
		return nil, &LineError{Status: "error", Error: err.Error()}
	}
	if q.op == "query_windows" && !q.stepGiven {
		return nil, &LineError{Status: "error", Error: `missing required field "step"`}
	}
	if q.start > q.end {
		return nil, &LineError{Status: "error", Error: fmt.Sprintf(
			`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
	}
	switch q.op {
	case "query_points":
		return s.runQueryPoints(q), nil
	case "query_windows":
		return s.runQueryWindows(q), nil
	default:
		return s.runQuery(q), nil
	}
}

// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
// 以及仅 query_windows 使用的 step；拒绝重复键与未知字段；标量必须是精确的
// JSON 类型，start/end 为 int64 毫秒。op 只接受 "query"（区间点数与均值）、
// "query_points"（区间采样明细）与 "query_windows"（固定窗口均值），三种操作
// 共用同一套字段校验与区间规则。
//
// 错误选择沿用既有次序：结构完整的对象按字段书写顺序暴露问题，已出现字段全部
// 合法后才按 op、name、start、end 的顺序报告缺失的必填字段（step 是否必填要
// 等 op 确定，其缺失由 queryFromObject 在四项必填齐全后判定）。step 是否合法
// 由操作本身决定，与 op 的书写位置无关：先用 decidedQueryOp 预扫对象，op 恰好
// 出现一次且为受支持操作时即已确定——query 与 query_points 携带 step 一律是
// 未知字段，无论 step 写在 op 前后、值是正整数、零、字符串还是对象，都在 step
// 自己的书写位置按未知字段拒绝，绝不退化成窗口宽度校验；query_windows 的 step
// 在出现处即按 JSON 正整数校验：int64 范围、大于零，缺失、类型不符或值不合法
// 都指出 step。op 缺失、重复、类型不符或取值未知时无法据此判定 step，回退到
// 既有行为：step 在出现处按窗口宽度校验，op 自身的问题仍按书写次序暴露。
func parseQuery(raw json.RawMessage) (parsedQuery, error) {
	var q parsedQuery
	q.basicGiven = map[string]bool{}
	decidedOp := decidedQueryOp(raw)
	err := parseStrictObject(raw,
		"each query must be a JSON object",
		"unexpected content after the query object",
		nil,
		map[string]fieldReader{
			"op": func(dec *json.Decoder) error {
				q.basicGiven["op"] = true
				t, err := dec.Token()
				if err != nil {
					return err
				}
				op, ok := t.(string)
				if !ok {
					return fmt.Errorf(`field "op" must be a string`)
				}
				if op != "query" && op != "query_points" && op != "query_windows" {
					return fmt.Errorf(`unknown op %q (only "query", "query_points" and "query_windows" are supported)`, op)
				}
				q.op = op
				return nil
			},
			"name": func(dec *json.Decoder) error {
				q.basicGiven["name"] = true
				return readNameField(dec, &q.name)
			},
			"start": func(dec *json.Decoder) error {
				q.basicGiven["start"] = true
				return readInt64Field(dec, "start", &q.start)
			},
			"end": func(dec *json.Decoder) error {
				q.basicGiven["end"] = true
				return readInt64Field(dec, "end", &q.end)
			},
			"labels": func(dec *json.Decoder) error {
				return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
			},
			"step": func(dec *json.Decoder) error {
				// 操作已确定且不是 query_windows：对该操作 step 是未知字段，
				// 不读其值，直接按书写次序拒绝（与 parseStrictObject 的未知字段
				// 处理一致）。确定的途径有两种：op 已写在 step 之前并成功读取
				// （q.op），或预扫发现 op 恰好出现一次且为受支持操作
				// （decidedOp，覆盖 step 写在 op 之前的情形）——两种途径下
				// step 的值都无关紧要，正整数、零、字符串、对象同样拒绝。
				if q.op != "" && q.op != "query_windows" {
					return fmt.Errorf(`unknown field "step"`)
				}
				if decidedOp == "query" || decidedOp == "query_points" {
					return fmt.Errorf(`unknown field "step"`)
				}
				if err := readInt64Field(dec, "step", &q.step); err != nil {
					return err
				}
				if q.step <= 0 {
					return fmt.Errorf(`field "step": must be greater than zero`)
				}
				q.stepGiven = true
				return nil
			},
		})
	if err != nil {
		return q, err
	}
	// op 写在 step 之后时，读完对象才知道 step 对该 op 是否合法；该判定属于
	// “已出现字段的合法性”，必须先于下面的必填字段缺失检查。op 本身缺失时不在这里
	// 判定 step 未知——请求可能是漏写 op 的 query_windows，交给下面的固定必填次序
	// 先报告 op（与“缺字段检查先于区间检查”等既有选择规则一致）。
	if q.stepGiven && q.op != "" && q.op != "query_windows" {
		return q, fmt.Errorf(`unknown field "step"`)
	}
	// 必填项固定按 op、name、start、end 的顺序报告第一个缺项，与字段书写位置无关。
	for _, field := range []string{"op", "name", "start", "end"} {
		if !q.basicGiven[field] {
			return q, fmt.Errorf("missing required field %q", field)
		}
	}
	return q, nil
}

// decidedQueryOp 预扫查询对象的顶层字段，确定用于判定 step 是否合法的操作：
// op 恰好出现一次且取值是三个受支持操作之一时返回该操作；其余情况（op 缺失、
// 重复出现、不是字符串或取值未知）返回空串，表示无法据此判定，step 的校验
// 回退到按窗口宽度进行的既有行为。预扫只读不写：字段的逐项校验与错误暴露
// 仍由 parseStrictObject 按书写次序完成，op 自身的类型错误、未知取值与重复
// 出现都在 op 的书写位置按既有措辞报告。键名比较与 parseStrictObject 一样
// 在转义还原后进行，因此以转义形式书写的 op 同样被识别。
func decidedQueryOp(raw json.RawMessage) string {
	dec := json.NewDecoder(bytes.NewReader(raw))
	tok, err := dec.Token()
	if err != nil {
		return ""
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return ""
	}
	op := ""
	opCount := 0
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return ""
		}
		key, _ := keyTok.(string)
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return ""
		}
		if key != "op" {
			continue
		}
		opCount++
		var s string
		if err := json.Unmarshal(value, &s); err != nil {
			return ""
		}
		op = s
	}
	if opCount != 1 {
		return ""
	}
	switch op {
	case "query", "query_points", "query_windows":
		return op
	}
	return ""
}

// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
func labelsMatch(want, stored map[string]string) bool {
	for k, v := range want {
		got, ok := stored[k]
		if !ok || got != v {
			return false
		}
	}
	return true
}

// matchSeries 筛出名称精确匹配且标签子集命中的已存序列，供三种查询操作各自整理；
// 只读，不改变存储。
func (s *MetricStore) matchSeries(q parsedQuery) []*storedSeries {
	matched := make([]*storedSeries, 0)
	for _, sr := range s.series {
		if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
			continue
		}
		matched = append(matched, sr)
	}
	return matched
}

// pointStats 是区间统计（query）与固定窗口统计（query_windows）共用的
// 点数与均值累计器：逐点累计个数与精确有理数总和。写入侧已保证值有限，
// SetFloat64 对有限值是精确的，因此求和与点的提交顺序、批次划分无关，
// 正负大数抵消后的微小余量不会丢失，总和超出 float64 有限范围时均值仍有限。
// 两种统计只在“哪些点归入哪一组”上不同，点数与均值规则统一由这里维护。
type pointStats struct {
	count int
	sum   *big.Rat
	tmp   *big.Rat
}

func newPointStats() *pointStats {
	return &pointStats{sum: new(big.Rat), tmp: new(big.Rat)}
}

// add 把一个实际保存的 float64 采样值计入统计。
func (a *pointStats) add(v float64) {
	a.count++
	a.sum.Add(a.sum, a.tmp.SetFloat64(v))
}

// reset 清空累计，供下一个互不影响的统计范围（如后一个窗口）复用同一累计器：
// 前一个范围的点数与数值一律不带入后一个范围。
func (a *pointStats) reset() {
	a.count = 0
	a.sum = new(big.Rat)
}

// average 返回精确算术平均舍入到最近可表示 float64 的结果（正中取偶；
// 精确为零时返回 +0）。调用方保证至少 add 过一次。不改动累计状态。
func (a *pointStats) average() float64 {
	return ratToFloat64NearestEven(new(big.Rat).Quo(a.sum, a.tmp.SetInt64(int64(a.count))))
}

// runQuery 只读统计已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
// 序列身份的整理（标签副本、排序键值对、排列次序）与写入快照共用同一套
// organizeSeries 规则，只是入选范围不同：这里先按名称与标签条件筛出命中序列
// 再整理，不为无关指标承担展示准备；筛后剩余序列的相对次序因此与写入全量
// 结果一致。查询只返回每条序列的点数与均值，不构造采样明细列表（明细由
// query_points 操作提供）——单次遍历点表直接累计进 pointStats（计数与
// 均值都与点的排列次序无关）。区间内没有点的序列不列出，不补零值条目。
func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
	organized := organizeSeries(s.matchSeries(q))

	out := make([]QuerySeries, 0, len(organized))
	for _, entry := range organized {
		// 一次遍历直接统计：不构造值切片、不排序时间戳，避免为只返回
		// count/average 的查询承担采样明细展示。点数与均值的累计和舍入
		// 规则与固定窗口统计共用 pointStats。
		stats := newPointStats()
		for ts, v := range entry.sr.points {
			if ts < q.start || ts > q.end {
				continue
			}
			stats.add(v)
		}
		if stats.count == 0 {
			continue
		}
		out = append(out, QuerySeries{
			Name:    entry.ref.Name,
			Labels:  entry.ref.Labels,
			Count:   stats.count,
			Average: stats.average(),
		})
	}
	return &QueryResult{Status: "ok", Op: "query", Series: out}
}

// runQueryPoints 只读列出已成功提交的采样明细：name 精确、标签子集、
// [start,end] 闭区间，与 runQuery 共用同一套序列筛选与 organizeSeries 整理
// 规则，因此序列排列次序与均值查询一致。每条命中序列保留完整指标名与完整
// 标签集合，points 按时间戳升序列出区间内的 timestamp 与 value，不附加
// count 或 average；区间内没有点的序列不列出，没有任何命中时 series 为
// 空数组。时间戳以 int64 比较与输出，保留整数精度；value 是实际存储的
// float64。查询只读，不改变采样值或写入计数。
func (s *MetricStore) runQueryPoints(q parsedQuery) *QueryPointsResult {
	organized := organizeSeries(s.matchSeries(q))

	out := make([]QueryPointsSeries, 0, len(organized))
	for _, entry := range organized {
		points := seriesPointsInRange(entry.sr, q.start, q.end)
		if len(points) == 0 {
			continue
		}
		out = append(out, QueryPointsSeries{
			Name:   entry.ref.Name,
			Labels: entry.ref.Labels,
			Points: points,
		})
	}
	return &QueryPointsResult{Status: "ok", Op: "query_points", Series: out}
}

// seriesPointsInRange 按 timestamp 升序返回一条已存序列在 [start,end] 闭区间
// 内的采样点，供采样明细查询展示。选取、升序排列与点构造与写入快照共用
// seriesPoints，区别只在传入的选取范围是闭区间而不是全部。
func seriesPointsInRange(sr *storedSeries, start, end int64) []Point {
	return seriesPoints(sr, func(ts int64) bool { return ts >= start && ts <= end })
}

// runQueryWindows 只读统计固定时间窗口内的点数与均值：窗口把 [start,end]
// 闭区间按 step 毫秒从 start 起连续划分，第 k 个窗口为
// [start+k*step, start+(k+1)*step-1]（含首尾毫秒），最后一个截到 end，
// 各序列共用同一组由 start 与 step 决定的边界——因此不为空窗口构造任何条目，
// 即使区间横跨整个 int64 也不预先物化窗口表。
//
// 名称精确、标签子集的序列筛选与 organizeSeries 整理、序列排列次序和另两种
// 查询完全一致。每条序列独立统计：先取区间内按时间戳升序的采样点，升序点流
// 中落在同一窗口的点必然连续，据此一次遍历分窗，逐窗口用 pointStats 累计
// 点数与均值——与区间统计共用同一套计数、精确求和与舍入规则；窗口切换时
// reset，前一窗口的点数与数值不带入后一窗口。只输出实际有点的窗口，按窗口
// 起点升序，空窗口不补零，整个区间没有点的序列不列出，无任何命中时 series
// 为空数组。每个点只归入 floor((ts-start)/step) 唯一窗口；start==end 时所有
// 点归入唯一窗口。平均值依据实际存储的 float64 值计算，正负大数抵消或总和
// 超出 float64 范围时仍得有限结果。查询只读，不改变存储。
func (s *MetricStore) runQueryWindows(q parsedQuery) *QueryWindowsResult {
	organized := organizeSeries(s.matchSeries(q))

	// diff = end - start，可能达到 2^64-1（start 为 MinInt64、end 为 MaxInt64），
	// 只能以 uint64 承载；窗口下标与窗口内偏移都在这个无符号区间内运算。
	diff := uint64(q.end) - uint64(q.start)

	out := make([]QueryWindowsSeries, 0, len(organized))
	for _, entry := range organized {
		points := seriesPointsInRange(entry.sr, q.start, q.end)
		if len(points) == 0 {
			continue
		}
		windows := make([]Window, 0)
		var curIdx uint64
		stats := newPointStats()
		flush := func() {
			windows = append(windows, buildWindow(q.start, q.end, q.step, diff, curIdx, stats))
		}
		for i, p := range points {
			// 无符号偏移除以 step 得窗口下标；升序点流下标单调不减。
			idx := (uint64(p.Timestamp) - uint64(q.start)) / uint64(q.step)
			if i > 0 && idx != curIdx {
				flush()
				stats.reset()
			}
			curIdx = idx
			stats.add(p.Value)
		}
		flush()
		out = append(out, QueryWindowsSeries{
			Name:    entry.ref.Name,
			Labels:  entry.ref.Labels,
			Windows: windows,
		})
	}
	return &QueryWindowsResult{Status: "ok", Op: "query_windows", Series: out}
}

// buildWindow 构造一个非空窗口的统计：窗口起点是 start + idx*step，终点是
// 起点加 step 减一；起点加 step 减一越过查询区间（含无符号加法溢出）时截到
// end。点数与均值取自该窗口独立累计的 stats，均值按与 query 相同的精确平均
// 与居中取偶规则得出（精确为零返回 +0）。调用方保证 0 <= idx*step <= diff，
// 且 stats 至少计入了一个点。
func buildWindow(start, end, step int64, diff, idx uint64, stats *pointStats) Window {
	startOff := idx * uint64(step)
	wStart := int64AtOffset(start, startOff)
	wEnd := end
	// tail <= diff-startOff 的比较不做 startOff+tail 加法，避免无符号溢出
	// （step 接近 2^63 时朴素相加可能绕过 2^64）。
	if tail := uint64(step) - 1; tail <= diff-startOff {
		wEnd = int64AtOffset(start, startOff+tail)
	}
	return Window{
		Start:   wStart,
		End:     wEnd,
		Count:   stats.count,
		Average: stats.average(),
	}
}

// int64AtOffset 返回 start + off（0 <= off，且调用方保证结果不超过 MaxInt64）。
// 直接做有符号相加在 start 接近 int64 下界、off 很大时会溢出，因此统一走
// 无符号运算还原：start 非负时无符号相加必落在非负有符号范围；start 为负时
// 以 -start 为界先回到非正区间、再跨入正区间，两个分支都不产生溢出。
func int64AtOffset(start int64, off uint64) int64 {
	if start >= 0 {
		return int64(uint64(start) + off)
	}
	gap := uint64(-start) // 0 < gap <= 2^63（start 为 MinInt64 时恰为 2^63）
	if off <= gap {
		// gap-off 为 2^63 时 int64 表示恰为 MinInt64，取负仍是 MinInt64，语义正确。
		return -int64(gap - off)
	}
	return int64(off - gap)
}

// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
func ratToFloat64NearestEven(x *big.Rat) float64 {
	if x.Sign() == 0 {
		return 0
	}
	num := new(big.Int).Set(x.Num())
	den := x.Denom()
	neg := num.Sign() < 0
	if neg {
		num.Neg(num)
	}

	// e 满足 2^e <= num/den < 2^(e+1)。
	e := floorLog2Rat(num, den)
	var m *big.Int
	scale := 0
	if e >= -1022 {
		// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
		scale = e - 52
		m = roundScaledRatio(num, den, scale)
		if m.BitLen() == 54 {
			// 舍入进位（如 1.111…1 进为 10.0），指数加一。
			m.Rsh(m, 1)
			scale++
		}
	} else {
		// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
		scale = -1074
		m = roundScaledRatio(num, den, scale)
	}
	// m < 2^53，可以精确放入 int64 与 float64。
	f := math.Ldexp(float64(m.Int64()), scale)
	if neg {
		return -f
	}
	return f
}

// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
func floorLog2Rat(num, den *big.Int) int {
	k := num.BitLen() - den.BitLen()
	var t big.Int
	if k >= 0 {
		t.Lsh(den, uint(k))
		if num.Cmp(&t) >= 0 {
			return k
		}
		return k - 1
	}
	t.Lsh(num, uint(-k))
	if t.Cmp(den) >= 0 {
		return k
	}
	return k - 1
}

// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
	n := new(big.Int).Set(num)
	d := new(big.Int).Set(den)
	if scale >= 0 {
		d.Lsh(d, uint(scale))
	} else {
		n.Lsh(n, uint(-scale))
	}
	q, r := new(big.Int).QuoRem(n, d, new(big.Int))
	switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
	case 1:
		q.Add(q, big.NewInt(1))
	case 0:
		if q.Bit(0) == 1 {
			q.Add(q, big.NewInt(1))
		}
	}
	return q
}

// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
// 与标签书写顺序、字符是否以 JSON 转义书写无关。
func (r SeriesRef) String() string {
	var b strings.Builder
	b.WriteString(identityText(r.Name))
	b.WriteByte('{')
	for i, p := range sortedPairs(r.Labels) {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(identityText(p.Key))
		b.WriteByte('=')
		b.WriteString(identityText(p.Value))
	}
	b.WriteByte('}')
	return b.String()
}

// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
// 因此渲染结果不会把内容字符误读为标签边界。
func identityText(s string) string {
	if s == "" || s != strings.TrimSpace(s) {
		return strconv.Quote(s)
	}
	for _, r := range s {
		if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
			return strconv.Quote(s)
		}
	}
	return s
}

// organizedSeries 是结果整理中的一条序列：携带已存序列指针、
// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
// 整理好的键值对，供排序比较直接复用。写入快照与区间查询都经由
// organizeSeries 得到这样的条目，区别只在入选的序列范围。
type organizedSeries struct {
	sr    *storedSeries
	ref   SeriesRef
	pairs []labelPair
}

// seriesLess 是写入快照与区间查询共用的序列次序约定：先按指标名字符串
// 字典序，同名再按标签键升序后的键值对逐对比较（先比键再比值，前一对
// 相同才比下一对；较短集合是完整前缀时排前，无标签序列因此排在最前）。
// 标签值按字符串比较（"10" 在 "2" 之前）。排序只看解析后的真实身份，
// 与冲突原因里的展示文字、标签的输入次序无关。
func seriesLess(a, b organizedSeries) bool {
	if a.ref.Name != b.ref.Name {
		return a.ref.Name < b.ref.Name
	}
	return compareLabelPairs(a.pairs, b.pairs) < 0
}

// organizeSeries 是写入快照与三种查询成功结果共用的序列身份整理：对入选的每条已存序列
// 复制独立的标签副本、预整理按键升序的键值对，并按 seriesLess 的统一次序
// 排列。入选范围由调用方决定：写入快照传入全部已提交序列，三种区间查询只
// 传入名称与标签条件命中的序列；它们因此遵循同一套整理规则而各自保留数据
// 范围。每条序列的标签只在入选时整理一次：排序后的键值对随条目保留，sort
// 的反复比较直接复用同一份结果，不会因一条序列参与多次比较而反复整理同一
// 套标签。整理结果不复制采样点；写入快照的采样点选取与升序排列由
// allSeriesPoints 完成，均值查询只在点表上计数与求和，采样明细查询由
// seriesPointsInRange 按区间选取并升序排列，固定窗口查询在区间升序点流上
// 按窗口累计计数与精确求和。
func organizeSeries(selected []*storedSeries) []organizedSeries {
	out := make([]organizedSeries, 0, len(selected))
	for _, sr := range selected {
		// 标签必须复制：成功结果是当次操作的独立记录，
		// 调用方修改结果标签不能改动已存序列的身份。
		labels := cloneLabels(sr.ref.Labels)
		out = append(out, organizedSeries{
			sr:    sr,
			ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
			pairs: sortedPairs(labels),
		})
	}
	sort.Slice(out, func(i, j int) bool { return seriesLess(out[i], out[j]) })
	return out
}

// allSeriesPoints 按 timestamp 升序返回一条已存序列的全部采样点，供写入快照
// 展示。选取、升序排列与点构造与采样明细查询共用 seriesPoints，区别只在传入
// 的选取范围是全部而不是闭区间。
func allSeriesPoints(sr *storedSeries) []Point {
	return seriesPoints(sr, nil)
}

// seriesPoints 是写入快照与采样明细查询共用的采样点整理：从已存序列的点表中
// 选出 keep 命中的时间戳（keep 为 nil 表示全部选取），按 timestamp 升序排列，
// 每个时间戳配上点表中实际存储的 value（数值与时间戳一一对应，排序只动时间戳
// 列表、不重配对值；int64 比较保留整数精度，float64 原样取出，负零保持负零）。
// 返回的是新建切片与新建 Point，不持有点表的任何引用：调用方对结果的修改不
// 影响存储，也不影响此前或此后取得的其他成功结果；取得结果后再写入新点，该份
// 结果也不跟随存储变化。均值查询不构造这样的明细列表，只在点表上计数与求和。
func seriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
	tsList := make([]int64, 0, len(sr.points))
	for ts := range sr.points {
		if keep != nil && !keep(ts) {
			continue
		}
		tsList = append(tsList, ts)
	}
	sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
	points := make([]Point, len(tsList))
	for i, ts := range tsList {
		points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
	}
	return points
}

// snapshot 生成按规范排序的全部序列视图：入选范围是全部已提交序列，
// 身份整理与次序来自 organizeSeries，点排列来自 allSeriesPoints；
// 三种区间查询共用同一套身份整理，各自只对命中序列统计均值、列出明细或
// 按固定窗口统计。
func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
	all := make([]*storedSeries, 0, len(s.series))
	for _, sr := range s.series {
		all = append(all, sr)
	}
	organized := organizeSeries(all)
	views := make([]SeriesView, 0, len(organized))
	for _, os := range organized {
		views = append(views, SeriesView{
			Name:   os.ref.Name,
			Labels: os.ref.Labels,
			Points: allSeriesPoints(os.sr),
		})
	}
	return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
}

package darksafe

import (
	"encoding/json"
	"fmt"
	"math/big"
	"reflect"
	"strings"
	"testing"
)

// 本文件回归保障两种只读查询在相同条件下描述的是同一组采样：用户在同一份
// 已成功写入的数据上发送 op 为 "query" 的查询，再仅把 op 改成 "query_points"
// （指标名、标签条件、起止时间完全相同），两次结果必须逐序列对应——同一组
// 采样，统计数字能与明细逐条对应：
//
//   - 两种结果的序列身份（指标名+完整标签集合）与排列次序完全一致，
//     记录中的标签是该序列的完整标签集合，不能缩减成查询条件；
//   - 每条统计记录的 count 等于对应明细中的采样点数量；
//   - average 是明细中实际存储的 float64 值的算术平均：测试侧独立用 big.Rat
//     精确求和、精确除以点数后舍入到最近可表示 float64（正中取偶），
//     不经过生产代码的 ratToFloat64NearestEven，从而能拦住“统计侧与复核侧
//     共用同一错误舍入实现”这类双侧同源错误；
//   - 同名指标不同标签的序列分别统计，不能混在一起计算；
//   - 只有闭区间 [start,end] 内的点参与某条记录的 count/average；
//   - 条件未命中任何区间内采样时两种查询都成功返回非 nil 空数组，
//     不把没有点的序列补成 count=0、average=0 的记录。
//
// 失败信息一律指出是哪个查询区间、哪条序列（以指标名+完整标签签名）的明细或
// 统计不符合上述关系，便于定位后续修改造成的查询偏差。

// queryPair 是除 op 外完全相同的一对查询文本：用户复核时只切换 op，
// 其余条件（指标名、标签条件、起止时间）保持不变。
type queryPair struct {
	note   string // 区间/场景的人类可读说明
	query  string // op 为 "query"
	points string // op 为 "query_points"
	start  int64  // 用于失败信息指明是哪个区间
	end    int64
}

// detailMean 用与生产实现无关的方式从明细点切片复算算术平均：每个值以其实际
// 存储的 float64 经 big.Rat.SetFloat64 精确入算，精确求和、精确除以点数，
// 再由 big.Rat.Float64 按 IEEE 754 最近偶规则舍入为 float64。它不调用生产
// 代码的手写舍入 ratToFloat64NearestEven，保证统计侧与复核侧不共用实现：
// 若 runQuery 的求和或舍入出错，从 query_points 明细独立复算的结果仍正确，
// 两侧差异即被查出。
func detailMean(t *testing.T, points []Point) float64 {
	t.Helper()
	if len(points) == 0 {
		t.Fatalf("internal: detailMean called with no points")
	}
	sum := new(big.Rat)
	r := new(big.Rat)
	for _, p := range points {
		sum.Add(sum, r.SetFloat64(p.Value))
	}
	sum.Quo(sum, big.NewRat(int64(len(points)), 1))
	// 有限 float64 值的精确平均必在 float64 有限范围内（凸组合），不会得到 Inf。
	f, _ := sum.Float64()
	return f
}

// assertQueryPairCorrespond 对同一区间执行两次查询（仅 op 不同），断言：
//   - 双方都成功，status/op 正确；
//   - 序列身份（name+完整标签）与排列次序逐一相同；
//   - 每条序列：统计 count == 明细点数，average == 从明细独立复算的精确平均
//     （最近偶 float64），两侧标签相同且为完整集合；
//   - 明细点时间戳严格升序、两两不同，且每个点都落在闭区间 [start,end] 内；
//   - 两侧都不出现没有点的空记录（不补 count=0/average=0 条目）；
//   - 空结果是成功的非 nil 空数组。
//
// 每个失败信息都带区间与序列身份签名，明确指出是哪条序列的明细或统计不符。
func assertQueryPairCorrespond(t *testing.T, store *MetricStore, p queryPair) {
	t.Helper()
	stats := mustQuery(t, store, p.query)
	detail := mustQueryPoints(t, store, p.points)
	if stats.Status != "ok" || stats.Op != "query" {
		t.Fatalf("[%d,%d] %s: stats envelope = %q/%q, want ok/query",
			p.start, p.end, p.note, stats.Status, stats.Op)
	}
	if detail.Status != "ok" || detail.Op != "query_points" {
		t.Fatalf("[%d,%d] %s: detail envelope = %q/%q, want ok/query_points",
			p.start, p.end, p.note, detail.Status, detail.Op)
	}

	// 序列数量、身份与排列次序逐一相同。
	if len(stats.Series) != len(detail.Series) {
		t.Fatalf("[%d,%d] %s: query returned %d series but query_points returned %d:\nstats:  %s\ndetail: %s",
			p.start, p.end, p.note, len(stats.Series), len(detail.Series),
			statsIdentitySigs(stats.Series), detailIdentitySigs(detail.Series))
	}
	for i := range stats.Series {
		sigSt := identitySig(stats.Series[i].Name, stats.Series[i].Labels)
		sigDe := identitySig(detail.Series[i].Name, detail.Series[i].Labels)
		if sigSt != sigDe {
			t.Fatalf("[%d,%d] %s: series[%d] identity/order mismatch:\nquery        #%d = %s\nquery_points #%d = %s",
				p.start, p.end, p.note, i, i, sigSt, i, sigDe)
		}
	}

	// 逐条核对 count/average 与明细的对应关系。
	for i := range stats.Series {
		stat := stats.Series[i]
		det := detail.Series[i]
		sig := identitySig(stat.Name, stat.Labels)

		// 两种结果携带的标签集合必须相同（且各场景已另行核对它是完整集合）。
		if !sameLabels(stat.Labels, det.Labels) {
			t.Fatalf("[%d,%d] %s: %s: labels differ between results: stats=%v detail=%v",
				p.start, p.end, p.note, sig, stat.Labels, det.Labels)
		}

		// count == 明细点数。
		if stat.Count != len(det.Points) {
			t.Fatalf("[%d,%d] %s: %s: count=%d but detail lists %d points: %+v",
				p.start, p.end, p.note, sig, stat.Count, len(det.Points), det.Points)
		}
		// 没有点的序列不能被任一侧补成零记录。
		if len(det.Points) == 0 {
			t.Fatalf("[%d,%d] %s: %s: zero-point entry must not be emitted by either query",
				p.start, p.end, p.note, sig)
		}

		// 明细按时间戳严格升序，且每个点都在闭区间内。
		for j, pt := range det.Points {
			if pt.Timestamp < p.start || pt.Timestamp > p.end {
				t.Fatalf("[%d,%d] %s: %s: detail point[%d] ts=%d is outside the closed range",
					p.start, p.end, p.note, sig, j, pt.Timestamp)
			}
			if j > 0 && det.Points[j-1].Timestamp >= pt.Timestamp {
				t.Fatalf("[%d,%d] %s: %s: detail not strictly ascending at %d: %+v",
					p.start, p.end, p.note, sig, j, det.Points)
			}
		}

		// average == 从明细独立复算的结果（精确平均 → 最近偶 float64）。
		wantAvg := detailMean(t, det.Points)
		if stat.Average != wantAvg {
			t.Fatalf("[%d,%d] %s: %s: average=%v but recomputed from the detail = %v (count=%d, detail=%+v)",
				p.start, p.end, p.note, sig, stat.Average, wantAvg, len(det.Points), det.Points)
		}
	}
}

// statsIdentitySigs / detailIdentitySigs 在数量不一致的失败信息中列出两侧
// 全部序列身份，指出究竟多/少了哪条序列。
func statsIdentitySigs(xs []QuerySeries) string {
	parts := make([]string, len(xs))
	for i, x := range xs {
		parts[i] = identitySig(x.Name, x.Labels)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func detailIdentitySigs(xs []QueryPointsSeries) string {
	parts := make([]string, len(xs))
	for i, x := range xs {
		parts[i] = identitySig(x.Name, x.Labels)
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

// pairsFor 用同一组条件构造仅 op 不同的一对查询文本。labels 为 nil 时省略
// labels 字段（匹配该指标全部序列）；非 nil 时显式带 labels（空 map 即 {}）。
func pairsFor(name string, start, end int64, labels map[string]string) queryPair {
	note := fmt.Sprintf("metric=%q range=[%d,%d]", name, start, end)
	if labels == nil {
		return queryPair{
			note:   note + " labels=<omit>",
			query:  queryAll(name, start, end),
			points: queryPointsAll(name, start, end),
			start:  start,
			end:    end,
		}
	}
	return queryPair{
		note:   note + " labels=" + jsonLabels(labels),
		query:  queryLabels(name, start, end, labels),
		points: queryPointsLabels(name, start, end, labels),
		start:  start,
		end:    end,
	}
}

// TestQueryAndPointsDescribeSameSamplesCancellation 是任务书指定的核心采样：
// 同一序列在 1000、2000、3000 分别存入 1e16、1、-1e16。包含三个点的区间内
// 明细按时间升序保留这三个存储值，统计 count=3、average=0.3333333333333333；
// 正负大数抵消不能吞掉中间的 1。该序列在区间外（500、4000）的采样，以及
// 同名但标签不同的另一条序列（host=b），都不改变这条记录的结果。
func TestQueryAndPointsDescribeSameSamplesCancellation(t *testing.T) {
	store := NewMetricStore()
	labelsA := map[string]string{"host": "a"}
	labelsB := map[string]string{"host": "b"}
	mustOK(t, store, "["+
		sample("cpu", 500, 77, labelsA)+","+ // 区间下方之外
		sample("cpu", 1000, 1e16, labelsA)+","+
		sample("cpu", 2000, 1, labelsA)+","+
		sample("cpu", 3000, -1e16, labelsA)+","+
		sample("cpu", 4000, 88, labelsA)+","+ // 区间上方之外
		// 同名但标签不同的另一条序列，值刻意取成若被混入就会改变 host=a 的均值。
		sample("cpu", 2000, 999999, labelsB)+"]")

	pair := pairsFor("cpu", 1000, 3000, labelsA)
	stats := mustQuery(t, store, pair.query)
	detail := mustQueryPoints(t, store, pair.points)

	// 明细侧：恰好一条 host=a 序列，三个点按时间升序，值是实际存储的 float64。
	if len(detail.Series) != 1 {
		t.Fatalf("[1000,3000] host=a: detail series = %s, want exactly 1 (host=b must be excluded)",
			detailIdentitySigs(detail.Series))
	}
	gotDetail := detail.Series[0]
	if !sameLabels(gotDetail.Labels, labelsA) {
		t.Fatalf("[1000,3000] %s: detail labels = %v, want full set %v",
			identitySig("cpu", labelsA), gotDetail.Labels, labelsA)
	}
	wantPoints := []Point{
		{Timestamp: 1000, Value: 1e16},
		{Timestamp: 2000, Value: 1},
		{Timestamp: 3000, Value: -1e16},
	}
	if !reflect.DeepEqual(gotDetail.Points, wantPoints) {
		t.Fatalf("[1000,3000] %s: detail points = %+v, want ascending %+v (out-of-range 500/4000 excluded)",
			identitySig("cpu", labelsA), gotDetail.Points, wantPoints)
	}

	// 统计侧：一条 host=a 记录，count=3，average 是 1/3 的最近 float64。
	if len(stats.Series) != 1 {
		t.Fatalf("[1000,3000] host=a: stats series = %s, want exactly 1", statsIdentitySigs(stats.Series))
	}
	s0 := stats.Series[0]
	if !sameLabels(s0.Labels, labelsA) {
		t.Fatalf("[1000,3000] %s: stats labels = %v, want full set %v (must not shrink to the query filter)",
			identitySig("cpu", labelsA), s0.Labels, labelsA)
	}
	if s0.Count != 3 {
		t.Fatalf("[1000,3000] %s: count = %d, want 3", identitySig("cpu", labelsA), s0.Count)
	}
	if s0.Average != 1.0/3.0 {
		t.Fatalf("[1000,3000] %s: average = %.17g, want %.17g (1/3 nearest float64); the middle 1 must survive cancellation",
			identitySig("cpu", labelsA), s0.Average, 1.0/3.0)
	}
	b, _ := json.Marshal(s0.Average)
	if string(b) != "0.3333333333333333" {
		t.Fatalf("[1000,3000] %s: average JSON = %s, want 0.3333333333333333",
			identitySig("cpu", labelsA), b)
	}

	// 通用对应关系校验（身份/次序、count==len(points)、独立复算平均、点在区间内且升序）。
	assertQueryPairCorrespond(t, store, pair)

	// 省略标签条件：host=a 与 host=b 同时返回，序列不能混算，排列次序两侧一致。
	both := pairsFor("cpu", 1000, 3000, nil)
	assertQueryPairCorrespond(t, store, both)
	statsAll := mustQuery(t, store, both.query)
	detailAll := mustQueryPoints(t, store, both.points)
	if len(statsAll.Series) != 2 || len(detailAll.Series) != 2 {
		t.Fatalf("[1000,3000] all-labels: series count stats=%d detail=%d, want 2",
			len(statsAll.Series), len(detailAll.Series))
	}
	// host=a 仍为 3 点、均值 1/3；host=b 单点 999999。
	qa := statsAll.Series[findQueryIndex(t, statsAll, "cpu", labelsA)]
	if qa.Count != 3 || qa.Average != 1.0/3.0 {
		t.Fatalf("host=a must stay separate from host=b: stats = %+v, want count=3 average=1/3", qa)
	}
	qb := statsAll.Series[findQueryIndex(t, statsAll, "cpu", labelsB)]
	if qb.Count != 1 || qb.Average != 999999 {
		t.Fatalf("host=b stats = %+v, want count=1 average=999999", qb)
	}
	da := detailAll.Series[findPointsIndex(t, detailAll, "cpu", labelsA)]
	if len(da.Points) != 3 {
		t.Fatalf("host=a detail must have exactly the 3 in-range points, got %+v", da.Points)
	}
	db := detailAll.Series[findPointsIndex(t, detailAll, "cpu", labelsB)]
	if !reflect.DeepEqual(db.Points, []Point{{Timestamp: 2000, Value: 999999}}) {
		t.Fatalf("host=b detail = %+v, want single point (2000,999999)", db.Points)
	}

	// 缩成只含两个端点的区间 [1000,2000]：host=a 统计基于两个大数，
	// 3000 上的 -1e16 不参与，均值为 0；明细也只有两个点。
	pair2 := pairsFor("cpu", 1000, 2000, nil)
	assertQueryPairCorrespond(t, store, pair2)
}

// TestQueryAndPointsSingleTimestampRange 区间端点语义：闭区间包含两个端点；
// start == end 且该位置有点时，明细只列那个点，统计 count=1、均值等于该点
// 的实际存储值。区间只命中序列部分点时，统计只基于命中的子集。
func TestQueryAndPointsSingleTimestampRange(t *testing.T) {
	store := NewMetricStore()
	labels := map[string]string{"host": "a"}
	mustOK(t, store, "["+
		sample("cpu", 1000, 2, labels)+","+
		sample("cpu", 2000, 4, labels)+","+
		sample("cpu", 3000, 9, labels)+"]")

	// start == end，逐位置核对明细只有该点、count==1、average==存储值本身。
	for _, want := range []Point{
		{Timestamp: 1000, Value: 2},
		{Timestamp: 2000, Value: 4},
		{Timestamp: 3000, Value: 9},
	} {
		pair := pairsFor("cpu", want.Timestamp, want.Timestamp, labels)
		detail := mustQueryPoints(t, store, pair.points)
		if len(detail.Series) != 1 || !reflect.DeepEqual(detail.Series[0].Points, []Point{want}) {
			t.Fatalf("[%d,%d] detail = %+v, want single point %+v",
				want.Timestamp, want.Timestamp, detail.Series, want)
		}
		stats := mustQuery(t, store, pair.query)
		if stats.Series[0].Count != 1 || stats.Series[0].Average != want.Value {
			t.Fatalf("[%d,%d] stats = %+v, want count=1 average=%v (the stored value itself)",
				want.Timestamp, want.Timestamp, stats.Series[0], want.Value)
		}
		assertQueryPairCorrespond(t, store, pair)
	}

	// 闭区间两个端点都包含，且区间只命中部分点时统计只基于命中的子集。
	assertQueryPairCorrespond(t, store, pairsFor("cpu", 1000, 2000, labels))
	assertQueryPairCorrespond(t, store, pairsFor("cpu", 1000, 3000, labels))
	assertQueryPairCorrespond(t, store, pairsFor("cpu", 1500, 2500, labels))
}

// TestQueryAndPointsSubsetMatchPreservesExtraLabels 按标签子集查询命中多条
// 序列时，两种结果的序列身份/次序一致，各条明细与统计分别对应；记录里保留
// 完整标签集合（包括查询条件之外的额外标签），不缩减成查询条件。
func TestQueryAndPointsSubsetMatchPreservesExtraLabels(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":10,"value":100,"labels":{"zone":"x"}},
		{"name":"m","timestamp":20,"value":200,"labels":{"zone":"x","host":"h"}},
		{"name":"m","timestamp":30,"value":300,"labels":{"zone":"x","host":"h2"}},
		{"name":"m","timestamp":40,"value":400,"labels":{"zone":"y"}},
		{"name":"m","timestamp":10,"value":500}
	]`)

	// 子集 zone=x 命中三条序列；查询条件只有一个标签，返回必须完整保留额外标签。
	pair := pairsFor("m", 0, 1000, map[string]string{"zone": "x"})
	assertQueryPairCorrespond(t, store, pair)
	stats := mustQuery(t, store, pair.query)
	detail := mustQueryPoints(t, store, pair.points)
	// 期望次序（host 键在前；"h" 是 "h2" 的前缀排前；单标签序列最后）。
	wantFullLabels := []map[string]string{
		{"host": "h", "zone": "x"},
		{"host": "h2", "zone": "x"},
		{"zone": "x"},
	}
	if len(stats.Series) != 3 || len(detail.Series) != 3 {
		t.Fatalf("zone=x subset stats=%d detail=%d, want 3 series",
			len(stats.Series), len(detail.Series))
	}
	for i, want := range wantFullLabels {
		if !sameLabels(stats.Series[i].Labels, want) {
			t.Fatalf("zone=x stats series[%d] labels = %v, want full set %v (must not shrink to the filter)",
				i, stats.Series[i].Labels, want)
		}
		if !sameLabels(detail.Series[i].Labels, want) {
			t.Fatalf("zone=x detail series[%d] labels = %v, want full set %v",
				i, detail.Series[i].Labels, want)
		}
	}
	// 各条明细与统计分别对应：host=h 是 (20,200)，host=h2 是 (30,300)，
	// 单标签 zone=x 是 (10,100)。
	if !reflect.DeepEqual(detail.Series[0].Points, []Point{{Timestamp: 20, Value: 200}}) {
		t.Fatalf("host=h detail = %+v, want (20,200)", detail.Series[0].Points)
	}
	if !reflect.DeepEqual(detail.Series[1].Points, []Point{{Timestamp: 30, Value: 300}}) {
		t.Fatalf("host=h2 detail = %+v, want (30,300)", detail.Series[1].Points)
	}
	if !reflect.DeepEqual(detail.Series[2].Points, []Point{{Timestamp: 10, Value: 100}}) {
		t.Fatalf("zone=x detail = %+v, want (10,100)", detail.Series[2].Points)
	}

	// 进一步限定到唯一带额外标签的序列：身份、count、average、额外标签都对。
	one := pairsFor("m", 0, 1000, map[string]string{"zone": "x", "host": "h"})
	assertQueryPairCorrespond(t, store, one)
	st := mustQuery(t, store, one.query)
	if !sameLabels(st.Series[0].Labels, map[string]string{"host": "h", "zone": "x"}) {
		t.Fatalf("fully-specified subset labels = %v, want full set", st.Series[0].Labels)
	}
	if st.Series[0].Count != 1 || st.Series[0].Average != 200 {
		t.Fatalf("fully-specified subset stats = %+v, want count=1 average=200", st.Series[0])
	}

	// 区间只命中部分序列：[15,25] 内只有 host=h 的 (20,200)；host=h2(ts=30)
	// 与单标签 zone=x(ts=10) 区间内无点，都不出现。
	partial := pairsFor("m", 15, 25, map[string]string{"zone": "x"})
	assertQueryPairCorrespond(t, store, partial)
	ps := mustQuery(t, store, partial.query)
	if len(ps.Series) != 1 || !sameLabels(ps.Series[0].Labels, map[string]string{"host": "h", "zone": "x"}) {
		t.Fatalf("[15,25] zone=x = %+v, want only the host=h series", ps.Series)
	}
}

// TestQueryAndPointsNoMatchBothEmpty 条件未命中任何区间内采样时，两种查询都
// 成功返回空 series 数组（非 nil，序列化为 []），不补零点数零均值记录——
// 包括指标不存在、标签条件无命中、标签命中但区间内无点、start==end 落在
// 没有点的位置；并覆盖省略 labels 与显式 {} 两种写法。
func TestQueryAndPointsNoMatchBothEmpty(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":2000,"value":5,"labels":{"host":"b"}}
	]`)

	cases := []queryPair{
		pairsFor("nope", 0, 5000, nil),                              // 指标不存在（省略 labels）
		pairsFor("nope", 0, 5000, map[string]string{}),              // 指标不存在（显式 {}）
		pairsFor("cpu", 0, 5000, map[string]string{"host": "zzz"}),  // 标签值不匹配
		pairsFor("cpu", 0, 5000, map[string]string{"zone": "x"}),    // 缺少该标签键
		pairsFor("cpu", 1001, 1999, nil),                            // 区间内没有点
		pairsFor("cpu", 2001, 9000, map[string]string{"host": "a"}), // 序列存在但区间在点之后
		pairsFor("cpu", 1000, 1000, map[string]string{"host": "b"}), // 标签命中但该时刻无点
		pairsFor("cpu", 1500, 1500, nil),                            // start==end 落在空位置
	}
	for _, p := range cases {
		t.Run(p.note, func(t *testing.T) {
			assertQueryPairCorrespond(t, store, p)
			stats := mustQuery(t, store, p.query)
			detail := mustQueryPoints(t, store, p.points)
			if stats.Series == nil || len(stats.Series) != 0 {
				t.Fatalf("stats series = %+v, want non-nil empty list", stats.Series)
			}
			if detail.Series == nil || len(detail.Series) != 0 {
				t.Fatalf("detail series = %+v, want non-nil empty list", detail.Series)
			}
			if raw := marshalCompact(t, stats); raw != `{"status":"ok","op":"query","series":[]}` {
				t.Fatalf("stats JSON = %s, want empty series []", raw)
			}
			if raw := marshalCompact(t, detail); raw != `{"status":"ok","op":"query_points","series":[]}` {
				t.Fatalf("detail JSON = %s, want empty series []", raw)
			}
		})
	}
}

// TestQueryAndPointsMultiSeriesRangesTable 用表格驱动覆盖多条同名不同标签
// 序列在多种区间下的对应关系。每条区间两种查询逐序列对应，统计都能从该区间
// 的明细独立复算；不同标签序列不串算、区间外点不参与。各序列在不同区间的
// count/average 刻意互不相同且非平凡，能区分“区间过滤错”“序列混算错”
// “次序串换错”三类回归。
func TestQueryAndPointsMultiSeriesRangesTable(t *testing.T) {
	store := NewMetricStore()
	// 三条同名不同标签序列（其中一条带额外标签）+ 一个不同名指标，
	// 时间戳部分重叠，使区间过滤与序列混算造成的差异各不相同。
	mustOK(t, store, "["+
		sample("m", 10, 2, map[string]string{"host": "a"})+","+
		sample("m", 20, 4, map[string]string{"host": "a"})+","+
		sample("m", 30, 6, map[string]string{"host": "a"})+","+
		sample("m", 40, 8, map[string]string{"host": "a"})+","+
		sample("m", 10, 20, map[string]string{"host": "b"})+","+
		sample("m", 20, 40, map[string]string{"host": "b"})+","+
		sample("m", 30, 60, map[string]string{"host": "b"})+","+
		sample("m", 25, 7, map[string]string{"dc": "1", "host": "c"})+","+
		sample("other", 20, 999, nil)+"]")

	cases := []struct {
		name   string
		metric string
		start  int64
		end    int64
		labels map[string]string // nil = 省略 labels
	}{
		{"all labels full range", "m", 0, 100, nil},
		{"all labels [20,30]", "m", 20, 30, nil},
		{"all labels single ts 20", "m", 20, 20, nil},
		{"all labels single ts 25 only host=c", "m", 25, 25, nil},
		{"all labels empty interior", "m", 11, 19, nil},
		{"host=a full", "m", 0, 100, map[string]string{"host": "a"}},
		{"host=a [15,35]", "m", 15, 35, map[string]string{"host": "a"}},
		{"host=a [30,40] endpoints", "m", 30, 40, map[string]string{"host": "a"}},
		{"host=b [10,20]", "m", 10, 20, map[string]string{"host": "b"}},
		{"host=b [25,100] one point", "m", 25, 100, map[string]string{"host": "b"}},
		{"host=b empty interior", "m", 11, 19, map[string]string{"host": "b"}},
		{"host=c keeps extra label", "m", 0, 100, map[string]string{"host": "c"}},
		{"host=c with dc subset", "m", 0, 100, map[string]string{"dc": "1", "host": "c"}},
		{"host=c wrong extra is empty", "m", 0, 100, map[string]string{"dc": "2", "host": "c"}},
		{"other metric by exact name", "other", 0, 100, nil},
		{"unknown metric empty", "nope", 0, 100, map[string]string{}},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			assertQueryPairCorrespond(t, store, pairsFor(c.metric, c.start, c.end, c.labels))
		})
	}

	// 点名核验几条非平凡统计，确保独立复算之外再锁死具体数字：
	// [20,30] 省略 labels：host=a 三点 (4,6? 实际 20->4,30->6) 均值 5；
	// host=b 两点 (40,60) 均值 50；host=c 在 25 的值 7。
	mid := mustQuery(t, store, queryAll("m", 20, 30))
	a := mid.Series[findQueryIndex(t, mid, "m", map[string]string{"host": "a"})]
	if a.Count != 2 || a.Average != 5 {
		t.Fatalf("[20,30] host-a = %+v, want count=2 average=5", a)
	}
	bq := mid.Series[findQueryIndex(t, mid, "m", map[string]string{"host": "b"})]
	if bq.Count != 2 || bq.Average != 50 {
		t.Fatalf("[20,30] host-b = %+v, want count=2 average=50", bq)
	}
	cq := mid.Series[findQueryIndex(t, mid, "m", map[string]string{"dc": "1", "host": "c"})]
	if cq.Count != 1 || cq.Average != 7 {
		t.Fatalf("[20,30] host-c = %+v, want count=1 average=7", cq)
	}
}

// TestQueryAndPointsIndependentRecomputationSpecialMeans 补强独立复算在两类
// 非平凡均值上的对应关系：朴素 float64 求和会溢出/丢精度的情形，以及精确
// 平均恰在两个相邻可表示值正中需要取偶的情形。统计值必须仍与明细逐条对应。
func TestQueryAndPointsIndependentRecomputationSpecialMeans(t *testing.T) {
	// 三点 1e308：朴素求和得到 +Inf，精确平均仍是有限的 1e308。
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":1,"value":1e308},
		{"name":"m","timestamp":2,"value":1e308},
		{"name":"m","timestamp":3,"value":1e308}
	]`)
	pair := pairsFor("m", 0, 100, nil)
	assertQueryPairCorrespond(t, store, pair)
	if s := mustQuery(t, store, pair.query).Series[0]; s.Count != 3 || s.Average != 1e308 {
		t.Fatalf("overflow-range mean = %+v, want count=3 average=1e308", s)
	}

	// 1 与下一个可表示值 1.0000000000000002 的精确平均恰在正中：取偶为 1。
	// 独立复算（big.Rat.Float64 的最近偶）与生产侧必须一致。
	store2 := NewMetricStore()
	mustOK(t, store2, `[
		{"name":"m","timestamp":1,"value":1},
		{"name":"m","timestamp":2,"value":1.0000000000000002}
	]`)
	pair2 := pairsFor("m", 1, 2, nil)
	assertQueryPairCorrespond(t, store2, pair2)
	if s := mustQuery(t, store2, pair2.query).Series[0]; s.Count != 2 || s.Average != 1 {
		t.Fatalf("tie-to-even = %+v, want count=2 average=1", s)
	}

	// 区间外再放一个点：缩小区间后明细与统计都只用区间内两点，取偶仍为 1；
	// 区间外点既不增加 count 也不改变舍入。
	mustOK(t, store2, `[{"name":"m","timestamp":3,"value":7}]`)
	pair3 := pairsFor("m", 1, 2, nil)
	assertQueryPairCorrespond(t, store2, pair3)
	if s := mustQuery(t, store2, pair3.query).Series[0]; s.Count != 2 || s.Average != 1 {
		t.Fatalf("out-of-range point changed the tie result: %+v", s)
	}
}

package darksafe

import (
	"encoding/json"
	"fmt"
	"math"
	"reflect"
	"strings"
	"testing"
)

// 本文件回归保障只读操作 query_windows：沿用 query 的查询条件（name 精确、
// labels 子集、[start,end] 闭区间）与序列整理/排列规则，但把区间按 step
// 毫秒从 start 起连续划分成含首尾毫秒的固定窗口，逐序列、逐窗口输出实际有点
// 窗口的 start、end、count、average。核心约定：
//
//   - 窗口为 [start+k*step, start+(k+1)*step-1]，最后一个截到 end；
//     区间 [1000,3000]、step 1000 时窗口为 [1000,1999]、[2000,2999]、[3000,3000]；
//   - 各序列共用同一组边界；每个点只归入一个窗口；start == end 时只有一个窗口；
//   - 只输出实际有点的窗口，按窗口起点升序，空窗口不补零；整个区间没有点的
//     序列不列出；无匹配时 series 为非 nil 空数组；
//   - 每条 series 保留完整指标名与完整标签集合，序列排列次序与另两种查询一致；
//   - count 统计窗口内已成功保存的点；average 沿用 query 的精确有理数平均与
//     居中取偶舍入，依据实际存储的 float64 值；
//   - step 必须是大于零且在 int64 范围内的 JSON 整数，且只用于 query_windows；
//   - 即使 start/end 接近 int64 上下界、step 接近 int64 上界，窗口也不溢出、
//     不倒置、不遗漏采样；
//   - 查询只读；失败是查询错误（无 index、无 conflict、无 series），保留行号，
//     后续输入照常处理；query 与 query_points 的行为保持兼容。

// mustQueryWindows 要求 query_windows 查询成功并返回窗口结果。
func mustQueryWindows(t *testing.T, store *MetricStore, line string) *QueryWindowsResult {
	t.Helper()
	res, err := store.QueryWindowsLine(line)
	if err != nil {
		t.Fatalf("expected query_windows success for %s, got error: %+v", line, err)
	}
	return res
}

// mustQueryWindowsFail 要求 query_windows 查询失败并返回结构化错误。
func mustQueryWindowsFail(t *testing.T, store *MetricStore, line string) *LineError {
	t.Helper()
	res, err := store.QueryWindowsLine(line)
	if err == nil {
		t.Fatalf("expected query_windows failure for %s, got result: %+v", line, res)
	}
	return err
}

// queryWindowsAll 构造省略 labels 的 query_windows 对象文本。
func queryWindowsAll(name string, start, end, step int64) string {
	return fmt.Sprintf(`{"op":"query_windows","name":%s,"start":%d,"end":%d,"step":%d}`,
		jsonString(name), start, end, step)
}

// queryWindowsLabels 构造按标签子集查询的 query_windows 对象文本。
func queryWindowsLabels(name string, start, end, step int64, labels map[string]string) string {
	return `{"op":"query_windows","name":` + jsonString(name) +
		fmt.Sprintf(`,"start":%d,"end":%d,"step":%d,"labels":`, start, end, step) +
		jsonLabels(labels) + `}`
}

func window(start, end int64, count int, avg float64) Window {
	return Window{Start: start, End: end, Count: count, Average: avg}
}

// assertWindows 断言一条序列的窗口列表与预期完全一致（含顺序）。
func assertWindows(t *testing.T, got []Window, want []Window, note string) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("%s: windows = %+v, want %+v", note, got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("%s: window[%d] = %+v, want %+v (full got %+v)", note, i, got[i], want[i], got)
		}
	}
}

// TestQueryWindowsSpecExample 任务书示例：区间 [1000,3000]、step 1000 时窗口为
// [1000,1999]、[2000,2999]、[3000,3000]，空窗口不补零。
func TestQueryWindowsSpecExample(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("cpu", 1000, 2, nil)+","+
		sample("cpu", 1500, 4, nil)+","+
		sample("cpu", 2000, 6, nil)+","+
		sample("cpu", 3000, 8, nil)+"]")

	res := mustQueryWindows(t, store, queryWindowsAll("cpu", 1000, 3000, 1000))
	if res.Status != "ok" || res.Op != "query_windows" {
		t.Fatalf("status/op = %q/%q, want ok/query_windows", res.Status, res.Op)
	}
	if len(res.Series) != 1 {
		t.Fatalf("series = %+v, want exactly one", res.Series)
	}
	s0 := res.Series[0]
	if s0.Name != "cpu" {
		t.Fatalf("series name = %q, want cpu", s0.Name)
	}
	assertWindows(t, s0.Windows, []Window{
		window(1000, 1999, 2, 3),
		window(2000, 2999, 1, 6),
		window(3000, 3000, 1, 8),
	}, "spec windows [1000,3000] step 1000")
}

// TestQueryWindowsResultShape 锁定成功结果的 JSON 形状：op 为 query_windows，
// 序列条目只有 name、labels、windows；窗口只有 start、end、count、average；
// 无命中时 series 是空数组而不是 null。
func TestQueryWindowsResultShape(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)

	res := mustQueryWindows(t, store, queryWindowsLabels("cpu", 1000, 3000, 1000, map[string]string{"host": "a"}))
	raw := marshalCompact(t, res)
	want := `{"status":"ok","op":"query_windows","series":[` +
		`{"name":"cpu","labels":{"host":"a"},"windows":[` +
		`{"start":1000,"end":1999,"count":1,"average":2}]}]}`
	if raw != want {
		t.Fatalf("query_windows JSON = %s, want %s", raw, want)
	}
	var decoded map[string]any
	if err := json.Unmarshal([]byte(raw), &decoded); err != nil {
		t.Fatal(err)
	}
	entry := decoded["series"].([]any)[0].(map[string]any)
	for _, banned := range []string{"count", "average", "points"} {
		if _, ok := entry[banned]; ok {
			t.Fatalf("query_windows series entry must not carry %q: %v", banned, entry)
		}
	}
	w0 := entry["windows"].([]any)[0].(map[string]any)
	if _, ok := w0["timestamp"]; ok {
		t.Fatalf("window must not carry timestamp: %v", w0)
	}

	// 无命中：成功的空 series 数组（非 null）。
	res = mustQueryWindows(t, store, queryWindowsAll("cpu", 2000, 3000, 1000))
	if res.Series == nil || len(res.Series) != 0 {
		t.Fatalf("miss query_windows = %+v, want non-nil empty series list", res.Series)
	}
	if raw = marshalCompact(t, res); raw != `{"status":"ok","op":"query_windows","series":[]}` {
		t.Fatalf("empty query_windows JSON = %s, want empty series array", raw)
	}
}

// TestQueryWindowsEmptyWindowsOmitted 空窗口不补零：只有实际有点的窗口列出，
// 窗口按起点升序；整条序列区间内没有点时不列出；无匹配序列时 series 为空。
func TestQueryWindowsEmptyWindowsOmitted(t *testing.T) {
	store := NewMetricStore()
	// host=a：窗口 0、2 有点，窗口 1 为空；host=b：整个区间没有点。
	mustOK(t, store, `[
		{"name":"cpu","timestamp":0,"value":2,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":1,"value":4,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":20,"value":6,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":21,"value":10,"labels":{"host":"a"}},
		{"name":"cpu","timestamp":99,"value":1,"labels":{"host":"b"}}
	]`)

	// labels 子集 host=a：只列窗口 0 与窗口 2，空窗口 1 不补零。
	res := mustQueryWindows(t, store, queryWindowsLabels("cpu", 0, 29, 10, map[string]string{"host": "a"}))
	if len(res.Series) != 1 {
		t.Fatalf("series = %+v, want exactly host=a", res.Series)
	}
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 9, 2, 3),
		window(20, 29, 2, 8),
	}, "empty middle window omitted")

	// 省略 labels 命中全部序列：host=b 在 [0,29] 内没有点，整个序列不列出。
	res = mustQueryWindows(t, store, queryWindowsAll("cpu", 0, 29, 10))
	if len(res.Series) != 1 || res.Series[0].Labels["host"] != "a" {
		t.Fatalf("series = %+v, want only host=a (host=b has no in-range points)", res.Series)
	}

	// 指标不存在 / 标签未命中 / 区间内无点：都是成功的空 series。
	for name, line := range map[string]string{
		"unknown metric":   queryWindowsAll("nope", 0, 29, 10),
		"label miss":       queryWindowsLabels("cpu", 0, 29, 10, map[string]string{"host": "zzz"}),
		"no points in itv": queryWindowsAll("cpu", 30, 40, 10),
	} {
		t.Run(name, func(t *testing.T) {
			r := mustQueryWindows(t, store, line)
			if r.Series == nil || len(r.Series) != 0 {
				t.Fatalf("%s: series = %+v, want empty", name, r.Series)
			}
		})
	}
}

// TestQueryWindowsSingleTimestamp start == end 时区间只有唯一窗口；落在该
// 时间戳上的点全部归入它，窗口终点等于 start。
func TestQueryWindowsSingleTimestamp(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("m", 5000, 2, nil)+","+
		sample("m", 5000, 2.0, nil)+"]") // 第二个是同值重复，不新增点

	res := mustQueryWindows(t, store, queryWindowsAll("m", 5000, 5000, 1))
	assertWindows(t, res.Series[0].Windows, []Window{window(5000, 5000, 1, 2)},
		"start==end, step=1")

	// step 远大于单点区间时唯一窗口仍是 [start,start]。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 5000, 5000, tsMaxInt64))
	assertWindows(t, res.Series[0].Windows, []Window{window(5000, 5000, 1, 2)},
		"start==end, huge step")

	// 单点区间无点：空 series。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 5001, 5001, 1))
	if len(res.Series) != 0 {
		t.Fatalf("series = %+v, want empty", res.Series)
	}
}

// TestQueryWindowsBoundariesAndAssignment 校验首尾毫秒归属：每个点只归入一个
// 窗口，窗口边界点（start+k*step - 1 与 start+k*step）分别落在相邻窗口。
func TestQueryWindowsBoundariesAndAssignment(t *testing.T) {
	store := NewMetricStore()
	// [10,39]、step=10：窗口 [10,19]、[20,29]、[30,39]，每个关键边界一个点。
	mustOK(t, store, `[
		{"name":"m","timestamp":10,"value":1},
		{"name":"m","timestamp":19,"value":3},
		{"name":"m","timestamp":20,"value":5},
		{"name":"m","timestamp":29,"value":7},
		{"name":"m","timestamp":30,"value":9},
		{"name":"m","timestamp":39,"value":11}
	]`)
	res := mustQueryWindows(t, store, queryWindowsAll("m", 10, 39, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(10, 19, 2, 2),
		window(20, 29, 2, 6),
		window(30, 39, 2, 10),
	}, "each boundary ms belongs to exactly one window")

	// 区间不是 step 的整数倍：最后一个窗口截到 end，而不是 end 对齐的完整窗口。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 10, 35, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(10, 19, 2, 2),
		window(20, 29, 2, 6),
		window(30, 35, 1, 9), // 39 上的点不在区间；窗口截到 35
	}, "last window clipped to end")

	// 区间比 step 宽但不足两个窗口：第一个完整窗口 + 长度为 1 的收尾窗口。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 10, 20, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(10, 19, 2, 2),
		window(20, 20, 1, 5),
	}, "width == step yields two windows touching at the boundary")

	// step 大于区间宽度：唯一窗口就是整个区间（截到 end）。
	res = mustQueryWindows(t, store, queryWindowsAll("m", 10, 39, 100))
	assertWindows(t, res.Series[0].Windows, []Window{window(10, 39, 6, 6)},
		"step wider than the range")
}

// TestQueryWindowsLabelsIdentityAndOrder 名称与标签筛选沿用现有查询：子集匹配、
// 完整标签集合保留、序列排列次序与 query/query_points 一致（先名字后排序标签）。
func TestQueryWindowsLabelsIdentityAndOrder(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":20,"value":2,"labels":{"zone":"x","host":"h"}},
		{"name":"m","timestamp":10,"value":1},
		{"name":"m","timestamp":30,"value":3,"labels":{"zone":"x"}},
		{"name":"other","timestamp":10,"value":9}
	]`)

	res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 25))
	if len(res.Series) != 3 {
		t.Fatalf("series = %+v, want 3", res.Series)
	}
	// 与 organizeSeries 的次序一致：无标签在前，其次 host=h,zone=x，最后 zone=x。
	wantIdentity := []struct {
		labels map[string]string
		win    []Window
	}{
		{map[string]string{}, []Window{window(0, 24, 1, 1)}},
		{map[string]string{"host": "h", "zone": "x"}, []Window{window(0, 24, 1, 2)}},
		{map[string]string{"zone": "x"}, []Window{window(25, 49, 1, 3)}},
	}
	for i, wi := range wantIdentity {
		s := res.Series[i]
		if s.Name != "m" || !sameLabels(s.Labels, wi.labels) {
			t.Fatalf("series[%d] = %+v, want identity m%v", i, s, wi.labels)
		}
		assertWindows(t, s.Windows, wi.win, fmt.Sprintf("series[%d]", i))
	}
	// 标签副本独立：修改结果不影响存储，再次查询一致。
	res.Series[0].Labels["injected"] = "y"
	res2 := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 25))
	if _, ok := res2.Series[0].Labels["injected"]; ok {
		t.Fatalf("result labels must be an independent copy, got %v", res2.Series[0].Labels)
	}

	// 子集匹配 zone=x：两条序列，返回完整标签集合而不缩减成查询条件。
	res = mustQueryWindows(t, store, `{"op":"query_windows","name":"m","start":0,"end":100,"step":25,"labels":{"zone":"x"}}`)
	if len(res.Series) != 2 {
		t.Fatalf("subset match = %+v, want 2 series", res.Series)
	}
	if !sameLabels(res.Series[0].Labels, map[string]string{"host": "h", "zone": "x"}) ||
		!sameLabels(res.Series[1].Labels, map[string]string{"zone": "x"}) {
		t.Fatalf("full label sets must be preserved: %+v", res.Series)
	}
}

// TestQueryWindowsCountAndAverageRules count 只统计已成功保存的点（等值重复
// 不增加），平均值依据实际存储的 float64、按 query 的精确平均与居中取偶规则。
func TestQueryWindowsCountAndAverageRules(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":0,"value":1},
		{"name":"m","timestamp":1,"value":1.0000000000000002}
	]`)
	// 同值重复：count 不增加。
	mustOK(t, store, `[{"name":"m","timestamp":0,"value":1.0}]`)

	res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 9, 10))
	// (1 + 1.0000000000000002)/2 恰居两者正中，取偶为 1；count=2（重复点不计）。
	assertWindows(t, res.Series[0].Windows,
		[]Window{window(0, 9, 2, 1)}, "nearest-even average over stored float64")

	// 每个窗口独立统计，窗口间不共享计数。
	mustOK(t, store, `[{"name":"m","timestamp":10,"value":10}]`)
	res = mustQueryWindows(t, store, queryWindowsAll("m", 0, 19, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 9, 2, 1),
		window(10, 19, 1, 10),
	}, "per-window independent counts")
}

// TestQueryWindowsLargeNumberCancellation 同一窗口内正负大数抵消后小余量保留，
// 且窗口内总和超出 float64 范围时平均仍有限——与 query 相同的精确有理数求和。
func TestQueryWindowsLargeNumberCancellation(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"x","timestamp":0,"value":1e16},
		{"name":"x","timestamp":1,"value":1},
		{"name":"x","timestamp":2,"value":-1e16},
		{"name":"x","timestamp":10,"value":1e308},
		{"name":"x","timestamp":11,"value":1e308}
	]`)
	res := mustQueryWindows(t, store, queryWindowsAll("x", 0, 19, 10))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 9, 3, 1.0/3.0), // big-rat 1/3 → nearest float64
		window(10, 19, 2, 1e308), // sum 2e308 overflows float64, mean stays finite
	}, "exact per-window arithmetic")
	if math.IsInf(res.Series[0].Windows[1].Average, 0) || math.IsNaN(res.Series[0].Windows[1].Average) {
		t.Fatalf("average must stay finite, got %v", res.Series[0].Windows[1].Average)
	}

	// 与同数据的整段 query 结果对照：query 同样精确求和，均值有限。
	qr := mustQuery(t, store, `{"op":"query","name":"x","start":0,"end":19}`)
	if len(qr.Series) != 1 || qr.Series[0].Count != 5 {
		t.Fatalf("query over same range = %+v, want count 5", qr.Series)
	}
	if math.IsInf(qr.Series[0].Average, 0) {
		t.Fatalf("query average must be finite, got inf")
	}
}

// TestQueryWindowsInt64Boundaries 起止时间与 step 接近 int64 上下界时窗口不
// 溢出、不倒置、不遗漏采样：覆盖跨整个 int64 区间、step 为 MaxInt64、
// start 为 MinInt64 等组合。
func TestQueryWindowsInt64Boundaries(t *testing.T) {
	min := tsMinInt64
	max := tsMaxInt64

	// 四个采样：MinInt64、-2、-1、MaxInt64；区间为整个 int64，step=MaxInt64。
	store := NewMetricStore()
	mustOK(t, store, "["+
		sample("m", min, 3, nil)+","+
		sample("m", -2, 9, nil)+","+
		sample("m", -1, 1, nil)+","+
		sample("m", max, 5, nil)+"]")
	res := mustQueryWindows(t, store, queryWindowsAll("m", min, max, max))
	// 窗口 0：[MinInt64, MinInt64+MaxInt64-1] = [MinInt64, -2]
	// 窗口 1：[-1, -1+MaxInt64-1] = [-1, MaxInt64-2]
	// 窗口 2：[MaxInt64-1, MaxInt64]（截到 end）
	assertWindows(t, res.Series[0].Windows, []Window{
		window(min, -2, 2, 6),
		window(-1, max-2, 1, 1),
		window(max-1, max, 1, 5),
	}, "full int64 range, step MaxInt64, no overflow/inversion")

	// step=1：每个时间戳独立窗口，首尾窗口的边界都精确。
	res = mustQueryWindows(t, store, queryWindowsAll("m", min, max, 1))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(min, min, 1, 3),
		window(-2, -2, 1, 9),
		window(-1, -1, 1, 1),
		window(max, max, 1, 5),
	}, "step 1 across full int64 range")

	// 负起点附近的小步划分：[-5,4]、step=3 → [-5,-3]、[-2,0]、[1,3]、[4,4]。
	store2 := NewMetricStore()
	for ts, v := range map[int64]float64{-5: 1, -3: 3, -2: 5, 0: 9, 1: 7, 3: 1, 4: 2} {
		mustOK(t, store2, "["+sample("m", ts, v, nil)+"]")
	}
	res = mustQueryWindows(t, store2, queryWindowsAll("m", -5, 4, 3))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(-5, -3, 2, 2),
		window(-2, 0, 2, 7),
		window(1, 3, 2, 4),
		window(4, 4, 1, 2),
	}, "negative start tiled without overflow")

	// start 为 MinInt64、end 为 -1（全负半区），step=MaxInt64：第一个窗口的
	// 自然终点 -2 未越过 end，保持完整宽度；第二个窗口从 -1 开始，截到 end=-1。
	res = mustQueryWindows(t, store, queryWindowsAll("m", min, -1, max))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(min, -2, 2, 6),
		window(-1, -1, 1, 1),
	}, "negative half, huge step clips second window to end")
}

// TestQueryWindowsStepValidation step 必须是大于零、int64 范围内的 JSON 整数；
// 缺失、类型不符、值不合法都返回指出 step 的查询错误。
func TestQueryWindowsStepValidation(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2}]`)

	cases := []struct {
		name string
		line string
		want string
	}{
		{"missing step", `{"op":"query_windows","name":"cpu","start":0,"end":1}`, `missing required field "step"`},
		{"step zero", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":0}`, `field "step"`},
		{"step negative", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":-1}`, `field "step"`},
		{"step string", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":"1"}`, `field "step" must be a JSON number`},
		{"step boolean", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":true}`, `field "step" must be a JSON number`},
		{"step null", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":null}`, `field "step" must be a JSON number`},
		{"step float", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":1.5}`, `field "step"`},
		{"step exponent fraction", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":1e0}`, `field "step"`},
		{"step over int64", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":9223372036854775808}`, `field "step"`},
		{"step under int64", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":-9223372036854775809}`, `field "step"`},
		{"step object", `{"op":"query_windows","name":"cpu","start":0,"end":1,"step":{}}`, `field "step" must be a JSON number`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			lerr := mustQueryWindowsFail(t, store, tc.line)
			assertQueryError(t, lerr, tc.want)
			// 失败结果没有 series、index 或 conflict。
			m := marshalLineError(t, lerr)
			for _, banned := range []string{"series", "index", "conflict"} {
				if _, ok := m[banned]; ok {
					t.Fatalf("query_windows failure must not carry %q: %v", banned, m)
				}
			}
		})
	}

	// 合法 step 恰好为 int64 上界：成功。
	res := mustQueryWindows(t, store, queryWindowsAll("cpu", 0, tsMaxInt64, tsMaxInt64))
	if res.Op != "query_windows" {
		t.Fatalf("step MaxInt64 must be accepted, got %+v", res)
	}
}

// TestQueryWindowsStepOnlyForNewOp step 只用于 query_windows：query 与
// query_points 携带 step 一律按未知字段拒绝；query_windows 仍可省略 labels。
func TestQueryWindowsStepOnlyForNewOp(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2}]`)

	// step 写在 op 之后：读到 step 立即按未知字段拒绝。
	lerr := mustQueryFail(t, store, `{"op":"query","name":"cpu","start":0,"end":2000,"step":1000}`)
	assertQueryError(t, lerr, `unknown field "step"`)
	lerr = mustQueryPointsFail(t, store, `{"op":"query_points","name":"cpu","start":0,"end":2000,"step":1000}`)
	assertQueryError(t, lerr, `unknown field "step"`)

	// step 写在 op 之前：读完对象再判未知字段，且该判定先于缺字段/区间检查。
	lerr = mustQueryFail(t, store, `{"step":1000,"op":"query","name":"cpu","start":0,"end":2000}`)
	assertQueryError(t, lerr, `unknown field "step"`)

	// step 写在 op 之前时，值是否合法不影响未知字段判定：零、字符串、对象
	// 都按未知字段拒绝，绝不退化成窗口宽度校验。
	for _, line := range []string{
		`{"step":0,"op":"query","name":"cpu","start":0,"end":2000}`,
		`{"step":"1000","op":"query","name":"cpu","start":0,"end":2000}`,
		`{"step":{},"op":"query","name":"cpu","start":0,"end":2000}`,
		`{"step":0,"op":"query_points","name":"cpu","start":0,"end":2000}`,
		`{"step":"1000","op":"query_points","name":"cpu","start":0,"end":2000}`,
		`{"step":{},"op":"query_points","name":"cpu","start":0,"end":2000}`,
	} {
		lerr = mustQueryFail(t, store, line)
		assertQueryError(t, lerr, `unknown field "step"`)
	}

	// 错误仍按字段书写次序选择：step 之前的字段错误先报；把错误字段移到
	// step 之后则先报 step，即使 op 写在它们之后也一样。
	lerr = mustQueryFail(t, store, `{"name":7,"step":1,"op":"query","start":0,"end":1}`)
	assertQueryError(t, lerr, `field "name" must be a string`)
	lerr = mustQueryFail(t, store, `{"step":1,"name":7,"op":"query","start":0,"end":1}`)
	assertQueryError(t, lerr, `unknown field "step"`)

	// step 的未知字段错误先于缺少必填项与区间倒置。
	lerr = mustQueryFail(t, store, `{"step":1,"op":"query"}`)
	assertQueryError(t, lerr, `unknown field "step"`)
	lerr = mustQueryFail(t, store, `{"step":1,"op":"query","name":"cpu","start":5,"end":1}`)
	assertQueryError(t, lerr, `unknown field "step"`)

	// 删掉 step 后原查询正常执行。
	qr := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":2000}`)
	if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 2 {
		t.Fatalf("query compatibility broken: %+v", qr.Series)
	}
	qp := mustQueryPoints(t, store, `{"op":"query_points","name":"cpu","start":0,"end":2000}`)
	if len(qp.Series) != 1 || len(qp.Series[0].Points) != 1 {
		t.Fatalf("query_points compatibility broken: %+v", qp.Series)
	}

	// op 缺失、类型错误、未知操作或重复出现时沿用既有处理：step 在出现处
	// 按窗口宽度校验，op 自身的问题按书写次序暴露。
	lerr = mustQueryFail(t, store, `{"step":0,"name":"cpu","start":0,"end":1}`)
	assertQueryError(t, lerr, `field "step"`)
	lerr = mustQueryFail(t, store, `{"step":0,"op":5,"name":"cpu","start":0,"end":1}`)
	assertQueryError(t, lerr, `field "step"`)
	lerr = mustQueryFail(t, store, `{"step":0,"op":"ping","name":"cpu","start":0,"end":1}`)
	assertQueryError(t, lerr, `field "step"`)
	lerr = mustQueryFail(t, store, `{"step":5,"op":"query","op":"query","name":"cpu","start":0,"end":1}`)
	assertQueryError(t, lerr, `duplicate field "op"`)
}

// TestQueryWindowsErrorSelection 失败原因的选择沿用查询对象的既有次序：
// 整行解析失败最先；已出现字段按书写顺序；缺字段在已出现字段合法之后；
// query_windows 特有“缺 step”排在四项必填之后、倒置区间之前。
func TestQueryWindowsErrorSelection(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2}]`)

	// 倒置区间 + 缺 step：四项必填齐全后先报缺 step（区间检查在最后）。
	lerr := mustQueryWindowsFail(t, store, `{"op":"query_windows","name":"cpu","start":5,"end":1}`)
	assertQueryError(t, lerr, `missing required field "step"`)

	// 倒置区间 + step 合法：才报区间倒置并给出实际边界。
	lerr = mustQueryWindowsFail(t, store, `{"op":"query_windows","name":"cpu","start":5,"end":1,"step":2}`)
	assertQueryError(t, lerr, `invalid range: "start" must not be greater than "end" (5 > 1)`)

	// 倒置区间 + 未知字段：先报未知字段（书写顺序）。
	lerr = mustQueryWindowsFail(t, store, `{"op":"query_windows","name":"cpu","start":5,"end":1,"step":2,"bogus":1}`)
	assertQueryError(t, lerr, `unknown field "bogus"`)

	// step 非法 + 倒置区间：step 字段问题先于区间检查。
	lerr = mustQueryWindowsFail(t, store, `{"op":"query_windows","name":"cpu","start":5,"end":1,"step":0}`)
	assertQueryError(t, lerr, `field "step"`)

	// 缺多项必填：仍按 op、name、start、end 的顺序；四项齐了才轮到 step。
	for _, tc := range []struct {
		line string
		want string
	}{
		{`{"start":0,"end":1,"step":1}`, `missing required field "op"`},
		{`{"op":"query_windows","start":0,"end":1,"step":1}`, `missing required field "name"`},
		{`{"op":"query_windows","name":"cpu","end":1,"step":1}`, `missing required field "start"`},
		{`{"op":"query_windows","name":"cpu","start":0,"step":1}`, `missing required field "end"`},
	} {
		lerr = mustQueryWindowsFail(t, store, tc.line)
		assertQueryError(t, lerr, tc.want)
	}

	// 未知 op：措辞覆盖三种操作。
	lerr = mustQueryWindowsFail(t, store, `{"op":"ping","name":"cpu","start":0,"end":1,"step":1}`)
	assertQueryError(t, lerr, `unknown op "ping"`)
	assertQueryError(t, lerr, "query_windows")

	// 整行解析失败最先（对象未闭合，即使字段类型已错）。
	lerr = mustQueryWindowsFail(t, store, `{"op":"query_windows","name":7,"step":1`)
	assertQueryError(t, lerr, "invalid JSON")
}

// TestQueryWindowsViaProcessLine 统一入口按 op 分派到 *QueryWindowsResult；
// 三个专用入口交叉使用时各自拒绝不属于自己的 op，且不返回另一类型的结果。
func TestQueryWindowsViaProcessLine(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2}]`)
	line := `{"op":"query_windows","name":"cpu","start":0,"end":2000,"step":1000}`

	r, lerr := store.ProcessLine(line)
	if lerr != nil || r == nil {
		t.Fatalf("ProcessLine query_windows: r=%v lerr=%+v", r, lerr)
	}
	qw, ok := r.(*QueryWindowsResult)
	if !ok {
		t.Fatalf("ProcessLine result type = %T, want *QueryWindowsResult", r)
	}
	if qw.Op != "query_windows" || len(qw.Series) != 1 {
		t.Fatalf("ProcessLine query_windows = %+v", qw)
	}

	// 倒置区间经统一入口失败：真正的 nil 结果。
	r, lerr = store.ProcessLine(`{"op":"query_windows","name":"cpu","start":9,"end":1,"step":2}`)
	if r != nil || lerr == nil || !strings.Contains(lerr.Error, "9 > 1") {
		t.Fatalf("inverted query_windows via ProcessLine: r=%v lerr=%+v", r, lerr)
	}

	// 专用入口交叉使用：各报各的引导信息，不串结果类型。
	if _, lerr = store.QueryLine(line); lerr == nil || !strings.Contains(lerr.Error, "query_windows") {
		t.Fatalf("QueryLine must reject query_windows, got %+v", lerr)
	}
	if _, lerr = store.QueryPointsLine(line); lerr == nil || !strings.Contains(lerr.Error, "query_windows") {
		t.Fatalf("QueryPointsLine must reject query_windows, got %+v", lerr)
	}
	if _, lerr = store.QueryWindowsLine(`{"op":"query","name":"cpu","start":0,"end":1}`); lerr == nil {
		t.Fatalf("QueryWindowsLine must reject op query")
	}
	if _, lerr = store.QueryWindowsLine(`{"op":"query_points","name":"cpu","start":0,"end":1}`); lerr == nil {
		t.Fatalf("QueryWindowsLine must reject op query_points")
	}
}

// TestQueryWindowsReadOnlyAndCommittedOnly query_windows 只读取此前成功提交的
// 数据：失败批次回滚的点不可见、等值重复不计入；查询不改变存储，与写入、
// query、query_points 交替进行互不影响。
func TestQueryWindowsReadOnlyAndCommittedOnly(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"m","timestamp":10,"value":2}]`)
	mustOK(t, store, `[{"name":"m","timestamp":20,"value":4}]`)

	baseline := func() {
		t.Helper()
		res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 50))
		want := []Window{window(0, 49, 2, 3)}
		if len(res.Series) != 1 {
			t.Fatalf("baseline series = %+v, want one", res.Series)
		}
		assertWindows(t, res.Series[0].Windows, want, "baseline")
	}
	baseline()

	// 失败批次整批回滚，窗口统计看不到其中任何点。
	mustFail(t, store, `[{"name":"m","timestamp":30,"value":8},{"name":"m","timestamp":10,"value":100}]`)
	baseline()

	// 等值重复不改变 count。
	mustOK(t, store, `[{"name":"m","timestamp":20,"value":4.0}]`)
	baseline()

	// 重复查询结果一致。
	r1 := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 50))
	r2 := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 50))
	if !reflect.DeepEqual(r1, r2) {
		t.Fatalf("repeated query_windows differs: %+v vs %+v", r1, r2)
	}

	// 存储未被改变：快照与另两种查询保持原状。
	snap := mustOK(t, store, `[]`)
	if len(snap.Series) != 1 || len(snap.Series[0].Points) != 2 {
		t.Fatalf("query_windows mutated storage, snapshot = %+v", snap.Series)
	}
	qr := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
	if qr.Series[0].Count != 2 || qr.Series[0].Average != 3 {
		t.Fatalf("query after query_windows = %+v", qr.Series)
	}

	// 后续写入可见：窗口统计随之增长。
	mustOK(t, store, `[{"name":"m","timestamp":60,"value":9}]`)
	res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 100, 50))
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 49, 2, 3),
		window(50, 99, 1, 9),
	}, "newly committed point appears in its window")
}

// TestQueryWindowsMultipleSeriesShareBoundaries 各序列共用同一组由 start 与
// step 决定的边界：不同序列的点在相同时间戳上归入相同窗口，输出窗口的
// start/end 一致；序列各自只列自己非空的窗口。
func TestQueryWindowsMultipleSeriesShareBoundaries(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":5,"value":1,"labels":{"h":"a"}},
		{"name":"m","timestamp":25,"value":3,"labels":{"h":"a"}},
		{"name":"m","timestamp":15,"value":7,"labels":{"h":"b"}}
	]`)
	res := mustQueryWindows(t, store, queryWindowsAll("m", 0, 39, 20))
	if len(res.Series) != 2 {
		t.Fatalf("series = %+v, want 2", res.Series)
	}
	// h=a 有点的窗口 0 与窗口 1；h=b 只有窗口 0——边界 [0,19]/[20,39] 相同。
	assertWindows(t, res.Series[0].Windows, []Window{
		window(0, 19, 1, 1),
		window(20, 39, 1, 3),
	}, "h=a windows")
	assertWindows(t, res.Series[1].Windows, []Window{
		window(0, 19, 1, 7),
	}, "h=b windows")
}

