1	package main
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"math/big"
7		"reflect"
8		"strings"
9		"testing"
10	)
11	
12	// 本文件从命令行入口（一次 ingest 进程内）回归保障用户的复核流程：在同一份
13	// 已成功写入的数据上发送 op 为 "query" 的对象行，再仅把 op 改成
14	// "query_points"（指标名、标签条件、起止时间逐字保持相同）。相邻两行输出必须
15	// 描述同一组采样：
16	//
17	//   - 两行 series 的序列身份（指标名+完整标签集合）与排列次序逐一相同；
18	//   - 统计行每条记录的 count 等于明细行对应序列的采样点数量；
19	//   - 统计行 average 等于明细点（经 JSON 往返后的 float64 存储值）用精确
20	//     有理数平均、最近偶舍入独立复算的结果；
21	//   - 明细点按时间戳升序且全部落在闭区间内；
22	//   - 标签子集命中多条序列时各条分别对应，额外标签完整保留；
23	//   - 条件未命中时两行都成功输出空 series 数组（[]），不补零记录。
24	//
25	// 与 darksafe 包内的 Go 级对应测试互补：这里数据真正经过 stdin 逐行写入、
26	// JSON 编码输出与退出码路径，保证用户在命令行上做的复核自洽。
27	
28	// cpSig 以规范 JSON（map 键排序）表示一条序列身份，用于把相邻两行的序列配对。
29	func cpSig(name string, labels map[string]interface{}) string {
30		b, _ := json.Marshal(struct {
31			Name   string                 `json:"name"`
32			Labels map[string]interface{} `json:"labels"`
33		}{name, labels})
34		return string(b)
35	}
36	
37	// cpSigs 按输出次序列出一行中全部序列的身份签名。
38	func cpSigs(series []interface{}) []string {
39		out := make([]string, len(series))
40		for i, e := range series {
41			m := e.(map[string]interface{})
42			out[i] = cpSig(m["name"].(string), m["labels"].(map[string]interface{}))
43		}
44		return out
45	}
46	
47	// cpDetailMean 从明细行的采样点独立复算算术平均：每个 JSON 往返后的 float64
48	// 值经 big.Rat 精确求和、精确除以点数，再按最近偶舍入为 float64。
49	func cpDetailMean(t *testing.T, points []interface{}) float64 {
50		t.Helper()
51		if len(points) == 0 {
52			t.Fatalf("internal: cpDetailMean with no points")
53		}
54		sum := new(big.Rat)
55		r := new(big.Rat)
56		for _, e := range points {
57			v := e.(map[string]interface{})["value"].(float64)
58			sum.Add(sum, r.SetFloat64(v))
59		}
60		sum.Quo(sum, big.NewRat(int64(len(points)), 1))
61		f, _ := sum.Float64()
62		return f
63	}
64	
65	// assertOutputPairCorrespond 核对相邻的 query / query_points 两条成功输出行
66	// 逐序列对应。start/end 用于失败信息指出区间，并验证明细点落在闭区间内。
67	func assertOutputPairCorrespond(t *testing.T, statsLine, detailLine string, start, end int64) {
68		t.Helper()
69		sm := decodeResultLine(t, statsLine)
70		dm := decodeResultLine(t, detailLine)
71		if sm["status"] != "ok" || sm["op"] != "query" {
72			t.Fatalf("[%d,%d] stats line = %v, want ok/query", start, end, sm)
73		}
74		if dm["status"] != "ok" || dm["op"] != "query_points" {
75			t.Fatalf("[%d,%d] detail line = %v, want ok/query_points", start, end, dm)
76		}
77		stats := sm["series"].([]interface{})
78		detail := dm["series"].([]interface{})
79		if len(stats) != len(detail) {
80			t.Fatalf("[%d,%d] series count: query=%d (%v), query_points=%d (%v)",
81				start, end, len(stats), cpSigs(stats), len(detail), cpSigs(detail))
82		}
83		for i := range stats {
84			se := stats[i].(map[string]interface{})
85			de := detail[i].(map[string]interface{})
86			sig := cpSig(se["name"].(string), se["labels"].(map[string]interface{}))
87			if sig != cpSig(de["name"].(string), de["labels"].(map[string]interface{})) {
88				t.Fatalf("[%d,%d] series[%d] identity/order mismatch: stats=%s detail=%s",
89					start, end, i,
90					cpSig(se["name"].(string), se["labels"].(map[string]interface{})),
91					cpSig(de["name"].(string), de["labels"].(map[string]interface{})))
92			}
93			points := de["points"].([]interface{})
94			count := int(se["count"].(float64))
95			if count != len(points) {
96				t.Fatalf("[%d,%d] %s: count=%d but detail has %d points",
97					start, end, sig, count, len(points))
98			}
99			if count == 0 {
100				t.Fatalf("[%d,%d] %s: a zero-point record must not appear in either line", start, end, sig)
101			}
102			// 明细时间戳严格升序，且全部在闭区间内。
103			var prevTS float64
104			for j, pe := range points {
105				pm := pe.(map[string]interface{})
106				ts := pm["timestamp"].(float64)
107				if ts < float64(start) || ts > float64(end) {
108					t.Fatalf("[%d,%d] %s: detail point[%d] ts=%v is outside the closed range",
109						start, end, sig, j, ts)
110				}
111				if j > 0 && prevTS >= ts {
112					t.Fatalf("[%d,%d] %s: detail points not strictly ascending at %d: %v",
113						start, end, sig, j, points)
114				}
115				prevTS = ts
116			}
117			// average 与明细独立复算一致（最近偶）。
118			wantAvg := cpDetailMean(t, points)
119			if got := se["average"].(float64); got != wantAvg {
120				t.Fatalf("[%d,%d] %s: average=%v but recomputed from detail = %v (points=%v)",
121					start, end, sig, got, wantAvg, points)
122			}
123		}
124	}
125	
126	// TestRunIngestQueryAndPointsCorrespondEndToEnd 是命令行端到端核心复核：
127	// 先写入任务书指定的采样（含区间外点与同名不同标签序列），随后成对发送
128	// 仅 op 不同的两种查询，逐对核对身份/次序/count/平均/明细。
129	func TestRunIngestQueryAndPointsCorrespondEndToEnd(t *testing.T) {
130		input := strings.Join([]string{
131			// 行 1：一次写入全部数据。
132			// host=a：区间外 500/4000，区间内 1000=1e16、2000=1、3000=-1e16。
133			`[{"name":"cpu","timestamp":500,"value":77,"labels":{"host":"a"}},` +
134				`{"name":"cpu","timestamp":1000,"value":10000000000000000,"labels":{"host":"a"}},` +
135				`{"name":"cpu","timestamp":2000,"value":1,"labels":{"host":"a"}},` +
136				`{"name":"cpu","timestamp":3000,"value":-10000000000000000,"labels":{"host":"a"}},` +
137				`{"name":"cpu","timestamp":4000,"value":88,"labels":{"host":"a"}},` +
138				// 同名不同标签的另一条序列，混入即改变 host=a 的均值。
139				`{"name":"cpu","timestamp":2000,"value":999999,"labels":{"host":"b"}},` +
140				// 另一个指标：子集命中两条，其中一条带查询条件之外的额外标签。
141				`{"name":"m","timestamp":10,"value":100,"labels":{"zone":"x"}},` +
142				`{"name":"m","timestamp":20,"value":200,"labels":{"zone":"x","host":"h"}},` +
143				`{"name":"m","timestamp":30,"value":400,"labels":{"zone":"y"}}]`,
144			// 行 2/3：host=a 的 [1000,3000]，仅 op 不同。
145			`{"op":"query","name":"cpu","start":1000,"end":3000,"labels":{"host":"a"}}`,
146			`{"op":"query_points","name":"cpu","start":1000,"end":3000,"labels":{"host":"a"}}`,
147			// 行 4/5：省略 labels 命中全部 cpu 序列（host=a 与 host=b）。
148			`{"op":"query","name":"cpu","start":1000,"end":3000}`,
149			`{"op":"query_points","name":"cpu","start":1000,"end":3000}`,
150			// 行 6/7：标签子集 zone=x 命中两条 m，额外 host 标签必须保留。
151			`{"op":"query","name":"m","start":0,"end":10000,"labels":{"zone":"x"}}`,
152			`{"op":"query_points","name":"m","start":0,"end":10000,"labels":{"zone":"x"}}`,
153			// 行 8/9：start==end 且该位置有点。
154			`{"op":"query","name":"cpu","start":2000,"end":2000,"labels":{"host":"a"}}`,
155			`{"op":"query_points","name":"cpu","start":2000,"end":2000,"labels":{"host":"a"}}`,
156			// 行 10/11：区间内没有任何点，两行都成功返回空数组。
157			`{"op":"query","name":"cpu","start":4001,"end":9000}`,
158			`{"op":"query_points","name":"cpu","start":4001,"end":9000}`,
159		}, "\n")
160	
161		var out strings.Builder
162		if code := runIngest(strings.NewReader(input), &out); code != 0 {
163			t.Fatalf("all lines succeed, exit code = %d, want 0", code)
164		}
165		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
166		if len(lines) != 11 {
167			t.Fatalf("got %d output lines, want 11: %v", len(lines), lines)
168		}
169	
170		// 行 2/3：核心取消例子——逐对身份/count/平均对应。
171		assertOutputPairCorrespond(t, lines[1], lines[2], 1000, 3000)
172		sm := decodeResultLine(t, lines[1])
173		dm := decodeResultLine(t, lines[2])
174		sStats := sm["series"].([]interface{})
175		sDetail := dm["series"].([]interface{})
176		if len(sStats) != 1 || len(sDetail) != 1 {
177			t.Fatalf("host=a [1000,3000]: lines must each have one cpu{host=a} entry, got %d/%d",
178				len(sStats), len(sDetail))
179		}
180		hostAStat := sStats[0].(map[string]interface{})
181		hostADetail := sDetail[0].(map[string]interface{})
182		if hostAStat["count"].(float64) != 3 || hostAStat["average"].(float64) != 1.0/3.0 {
183			t.Fatalf("host-a stats = %v, want count=3 average=1/3 (middle 1 must survive cancellation)",
184				hostAStat)
185		}
186		if b, _ := json.Marshal(hostAStat["average"]); string(b) != "0.3333333333333333" {
187			t.Fatalf("host-a average JSON = %s, want 0.3333333333333333", b)
188		}
189		wantPoints := []map[string]float64{
190			{"timestamp": 1000, "value": 1e16},
191			{"timestamp": 2000, "value": 1},
192			{"timestamp": 3000, "value": -1e16},
193		}
194		gotPoints := hostADetail["points"].([]interface{})
195		if len(gotPoints) != 3 {
196			t.Fatalf("host-a detail points = %v, want 3 ascending points", gotPoints)
197		}
198		for i, w := range wantPoints {
199			gp := gotPoints[i].(map[string]interface{})
200			if gp["timestamp"].(float64) != w["timestamp"] || gp["value"].(float64) != w["value"] {
201				t.Fatalf("host-a detail point[%d] = %v, want %v (out-of-range 500/4000 excluded)",
202					i, gp, w)
203			}
204		}
205	
206		// 行 4/5：全部 cpu 序列分别统计，host=a 与 host=b 不混算。
207		assertOutputPairCorrespond(t, lines[3], lines[4], 1000, 3000)
208		allStats := decodeResultLine(t, lines[3])["series"].([]interface{})
209		allDetail := decodeResultLine(t, lines[4])["series"].([]interface{})
210		if len(allStats) != 2 || len(allDetail) != 2 {
211			t.Fatalf("all cpu series: want 2 entries in both lines, got %d/%d",
212				len(allStats), len(allDetail))
213		}
214		bySig := func(series []interface{}) map[string]map[string]interface{} {
215			m := make(map[string]map[string]interface{})
216			for _, e := range series {
217				em := e.(map[string]interface{})
218				m[cpSig(em["name"].(string), em["labels"].(map[string]interface{}))] = em
219			}
220			return m
221		}(allStats)
222		if e := bySig[cpSig("cpu", map[string]interface{}{"host": "a"})]; e["count"].(float64) != 3 ||
223			e["average"].(float64) != 1.0/3.0 {
224			t.Fatalf("host=a must stay separate: %v, want count=3 average=1/3", e)
225		}
226		if e := bySig[cpSig("cpu", map[string]interface{}{"host": "b"})]; e["count"].(float64) != 1 ||
227			e["average"].(float64) != 999999 {
228			t.Fatalf("host=b must be its own record: %v, want count=1 average=999999", e)
229		}
230		// 两行的序列次序也必须一致（host=a 在前、host=b 在后）。
231		if !reflect.DeepEqual(cpSigs(allStats), cpSigs(allDetail)) {
232			t.Fatalf("series order differs between lines: stats=%v detail=%v",
233				cpSigs(allStats), cpSigs(allDetail))
234		}
235	
236		// 行 6/7：子集 zone=x 命中两条 m，额外 host 标签完整保留，各条分别对应。
237		assertOutputPairCorrespond(t, lines[5], lines[6], 0, 10000)
238		mStats := decodeResultLine(t, lines[5])["series"].([]interface{})
239		mDetail := decodeResultLine(t, lines[6])["series"].([]interface{})
240		if len(mStats) != 2 || len(mDetail) != 2 {
241			t.Fatalf("zone=x subset: want 2 m series in both lines, got %d/%d",
242				len(mStats), len(mDetail))
243		}
244		// 期望次序：带 host=h 额外标签的在前（host < zone），单标签在后。
245		wantSigs := []string{
246			cpSig("m", map[string]interface{}{"host": "h", "zone": "x"}),
247			cpSig("m", map[string]interface{}{"zone": "x"}),
248		}
249		if got := cpSigs(mStats); !reflect.DeepEqual(got, wantSigs) {
250			t.Fatalf("zone=x stats order = %v, want %v", got, wantSigs)
251		}
252		if got := cpSigs(mDetail); !reflect.DeepEqual(got, wantSigs) {
253			t.Fatalf("zone=x detail order = %v, want %v", got, wantSigs)
254		}
255		// 额外标签必须真实出现在记录里（不能缩减成查询条件 {"zone":"x"}）。
256		extraLabels := mStats[0].(map[string]interface{})["labels"].(map[string]interface{})
257		if _, hasHost := extraLabels["host"]; !hasHost || len(extraLabels) != 2 {
258			t.Fatalf("extra label dropped from stats record: %v", extraLabels)
259		}
260		extraDetailLabels := mDetail[0].(map[string]interface{})["labels"].(map[string]interface{})
261		if _, hasHost := extraDetailLabels["host"]; !hasHost || len(extraDetailLabels) != 2 {
262			t.Fatalf("extra label dropped from detail record: %v", extraDetailLabels)
263		}
264	
265		// 行 8/9：start==end 单点，count=1、平均等于该点存储值。
266		assertOutputPairCorrespond(t, lines[7], lines[8], 2000, 2000)
267		oneStat := decodeResultLine(t, lines[7])["series"].([]interface{})
268		oneDetail := decodeResultLine(t, lines[8])["series"].([]interface{})
269		if len(oneStat) != 1 || oneStat[0].(map[string]interface{})["count"].(float64) != 1 ||
270			oneStat[0].(map[string]interface{})["average"].(float64) != 1 {
271			t.Fatalf("[2000,2000] stats = %v, want count=1 average=1", oneStat)
272		}
273		if pts := oneDetail[0].(map[string]interface{})["points"].([]interface{}); len(pts) != 1 ||
274			pts[0].(map[string]interface{})["timestamp"].(float64) != 2000 ||
275			pts[0].(map[string]interface{})["value"].(float64) != 1 {
276			t.Fatalf("[2000,2000] detail = %v, want single (2000,1)", pts)
277		}
278	
279		// 行 10/11：无命中两行都成功返回空数组（[] 而非 null），不补零记录。
280		for i, line := range []string{lines[9], lines[10]} {
281			m := decodeResultLine(t, line)
282			op := [...]string{"query", "query_points"}[i]
283			if m["status"] != "ok" || m["op"] != op {
284				t.Fatalf("empty %s line = %v, want ok/%s", op, m, op)
285			}
286			if series, ok := m["series"].([]interface{}); !ok || len(series) != 0 {
287				t.Fatalf("empty %s series = %v, want empty array []", op, m["series"])
288			}
289			// 原始 JSON 必须是 []，不能是 null，也不能出现 count:0/average:0 记录。
290			if !strings.Contains(line, `"series":[]`) {
291				t.Fatalf("empty %s JSON = %s, want \"series\":[]", op, line)
292			}
293			if strings.Contains(line, `"count":0`) || strings.Contains(line, `"average":0`) {
294				t.Fatalf("empty %s must not fabricate zero records: %s", op, line)
295			}
296		}
297	}
298	
299	// TestRunIngestQueryAndPointsIdentityOrderStableAcrossPairs 多写几条同名序列，
300	// 验证在多个不同区间重复“query 后紧跟 query_points”时，两行身份次序始终一致，
301	// 且与写入快照的规范次序（无标签在前，其后按标签键值对字典序）相同；区间只
302	// 命中部分序列时，两行保留的必须是同一个子序列。
303	func TestRunIngestQueryAndPointsIdentityOrderStableAcrossPairs(t *testing.T) {
304		var b strings.Builder
305		b.WriteString(`[`)
306		// host=a..d 与无标签共 5 条 cpu 序列，时间戳与值互不相同，使次序串换或
307		// 跨序列混算都会改变某条记录的 count/average 而被抓住。
308		samples := []struct {
309			ts    int
310			value int
311			host  string
312		}{
313			{10, 1, "d"}, {20, 2, "c"}, {30, 3, "b"}, {40, 4, "a"}, {50, 5, ""},
314		}
315		for i, sp := range samples {
316			if i > 0 {
317				b.WriteByte(',')
318			}
319			if sp.host == "" {
320				fmt.Fprintf(&b, `{"name":"cpu","timestamp":%d,"value":%d}`, sp.ts, sp.value)
321			} else {
322				fmt.Fprintf(&b, `{"name":"cpu","timestamp":%d,"value":%d,"labels":{"host":"%s"}}`,
323					sp.ts, sp.value, sp.host)
324			}
325		}
326		b.WriteString("]\n")
327	
328		// 规范次序：无标签在前，其后 host=a、b、c、d。
329		sigUnlabeled := cpSig("cpu", map[string]interface{}{})
330		sigA := cpSig("cpu", map[string]interface{}{"host": "a"})
331		sigB := cpSig("cpu", map[string]interface{}{"host": "b"})
332		sigC := cpSig("cpu", map[string]interface{}{"host": "c"})
333		sigD := cpSig("cpu", map[string]interface{}{"host": "d"})
334	
335		ranges := []struct {
336			start, end int
337			want       []string
338		}{
339			{0, 100, []string{sigUnlabeled, sigA, sigB, sigC, sigD}},
340			{15, 45, []string{sigA, sigB, sigC}}, // 命中 a(40)、b(30)、c(20)
341			{20, 40, []string{sigA, sigB, sigC}},
342			{30, 30, []string{sigB}}, // 只命中 b(30,3)
343			{60, 90, []string{}},     // 区间内无点
344		}
345		for _, rr := range ranges {
346			fmt.Fprintf(&b, `{"op":"query","name":"cpu","start":%d,"end":%d}`+"\n", rr.start, rr.end)
347			fmt.Fprintf(&b, `{"op":"query_points","name":"cpu","start":%d,"end":%d}`+"\n", rr.start, rr.end)
348		}
349	
350		var out strings.Builder
351		if code := runIngest(strings.NewReader(b.String()), &out); code != 0 {
352			t.Fatalf("all lines succeed, exit code = %d, want 0", code)
353		}
354		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
355		if want := 1 + 2*len(ranges); len(lines) != want {
356			t.Fatalf("got %d output lines, want %d", len(lines), want)
357		}
358		for i, rr := range ranges {
359			statsLine := lines[1+2*i]
360			detailLine := lines[2+2*i]
361			assertOutputPairCorrespond(t, statsLine, detailLine, int64(rr.start), int64(rr.end))
362			ss := cpSigs(decodeResultLine(t, statsLine)["series"].([]interface{}))
363			ds := cpSigs(decodeResultLine(t, detailLine)["series"].([]interface{}))
364			// 两行身份次序彼此一致，且正是规范次序在该区间上的子序列。
365			if !reflect.DeepEqual(ss, rr.want) {
366				t.Fatalf("range [%d,%d] stats order = %v, want canonical %v", rr.start, rr.end, ss, rr.want)
367			}
368			if !reflect.DeepEqual(ds, rr.want) {
369				t.Fatalf("range [%d,%d] detail order = %v, want canonical %v", rr.start, rr.end, ds, rr.want)
370			}
371		}
372	}
